INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('fd8dc229fcae07f9d46f','Pediatric amedex 2025.pdf','95','Paediatrics','Six days after an uneventful tonsillectomy on a 7-year-old boy, he is brought back to the emergency department after
coughing up blood 30 minutes earlier. Which one of the following would be the next best step in management?','{"A":"A. Packing.","B":"B. Oral antibiotics.","C":"OC. Intravenous antibiotics.","D":"D. Take him back to the operating room for exploration.","E":"E. Give him ice cream and cold fluids."}','C','Hemorrhage after tonsillectomy is the most common complication of the procedure. The bleeding may occur in the early
post-operative period or may be as delayed as 5 to 10 days. Late bleeding is normally secondary to infection of the tonsillar
fossae. Typically, there is initially minor bleeding, but blood-pouring develops afterwards; therefore any bleeding even trivial
must be considered serious in all cases. Post-tonsillectomy hemorrhage is a life-threatening condition, which requires
prompt management in all cases (even if only little blood is spat out and bleeding stops again — all these cases should be
dealt with caution — particularly the children).

NOTE -— The chance of post-tonsillectomy hemorrhage increases with age.

On physical examination, a hint of blood in a corner of one of the tonsillar fossae may be noticed. Small grey or clotted
blood is another likely fkinding. Parents of younger children may describe finding blood on the child’s pillowcase, or an
episode of hemoptysis or hematemesis. Excessive swallowing may also be an indicator of ongoing bleeding in young
children

Management of post-tonsillectomy hemorrhage includes:

¢ Resuscitation — 2 large bore cannula with bloods

¢ Reservation of cross-matched packed red cells

¢ Intravenous antibiotics: with 1.2g Benzyl Penicillin, 6-hourly + 500mg of metronidazole, 12-hourly

e Analgesia without NSAIDs (NSAIDs may increase the chance of bleeding)

¢ Hydrogen peroxide gargle - 20mls of hydrogen peroxide diluted with water in a ratio of 1:6. This gargle should be
used every 4 hours; it should be used when a large clot overlies one of the tonsil beds.

Of the given options, the only one in the management plan of this patient is administration of intravenous antibiotics.
(Option A) Packing the tonsils is neither practical nor effective.

(Option B) Antibiotics in oral forms are not recommended for management.

(Option D) Exploration might be indicated; however, most patients will respond to more conservative managements.

(Option E) The patient should be kept nil by mouth (NBM) because it is very likely that emergency surgery becomes
inevitable; therefore giving him ice cream or cold fluids is an incorrect option.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[95],"source_qid":null,"duplicate_group_id":"exact-7fa3851cff83","duplicate_sources":[{"record_id":"fd8dc229fcae07f9d46f","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":95,"source_qid":null},{"record_id":"efe4df271aaccf665d8e","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":159,"source_qid":null},{"record_id":"87e472ebbccb375e7960","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":158,"source_qid":null},{"record_id":"0e091c8b3c4a787da45b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1246,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"fd8dc229fcae07f9d46f","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":95,"supporting_pages":[95],"source_qid":null,"domain_hint":"Paediatrics","stem":"Six days after an uneventful tonsillectomy on a 7-year-old boy, he is brought back to the emergency department after\ncoughing up blood 30 minutes earlier. Which one of the following would be the next best step in management?","options":{"A":"A. Packing.","B":"B. Oral antibiotics.","C":"OC. Intravenous antibiotics.","D":"D. Take 