INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('0ce71c4b24959c22a68b','Pediatric amedex 2025.pdf','97','Paediatrics','Tanya has brought her 2-year-old son to your clinic, disgruntled and annoyed by the child’s condition. She tells you that 2
months ago, she started to wean the child onto solid foods and currently his diet includes breastfeeding 3 times a day 5
minutes from each of her breasts and a bowl of cereal and rice every morning. The child has dropped from the 50" to 25th
percentile. The child’s past medical history is remarkable for one episode of admission due to bronchiolitis. Which one of
the following is the most likely cause of this baby’s diminished weight gain?','{"A":"A. Cystic fibrosis.","B":"B. Celiac disease.","C":"OC. Low calorie intake.","D":"D. Child abuse.","E":"E. Normal physiologic response to weaning."}','C','With a drop in growth percentile, this child has developed failure to thrive.
Failure to thrive is defined as either of the following:

¢ Body mass index for age less than the 5th

5th

percentile

e Length for age less than the percentile
¢ Weight deceleration crossing two major percentile lines

¢ Weight for age less than 50th percentile
¢ Weight less than 75% of median weight for age
¢ Weight less than 75% of median weight for length

¢ Weight velocity less than the 5th percentile

The most common cause of failure to thrive is inadequate caloric intake. With 3 sessions of breast feeding and only one
bowl of cereal, this baby is definitely receiving far less than his caloric needs and therefore, low caloric intake would be the
most likely cause of his problem.

(Option A) With only one episode of bronchiolitis, the child is unlikely to have cystic fibrosis. Patients with cystic fibrosis
often have respiratory infection recurrences.

(Option B) Celiac disease can be a possibility, especially considering the fact that this child has been started on cereal and
rice, both of which contain gluten, but celiac disease is far less common than inadequate calorie intake. Furthermore, the
child with celiac disease has more pronounced symptoms e.g., diarrhea.

(Option D) Child abuse seems unlikely because firstly there is no comment in the question pointing towards the likelinood
of child abuse and secondly, the mother seems concerned about her child’s condition and has sought medical care.

(Option E) Normal physiologic response to weaning could be considered if the baby was receiving adequate nutrition.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[97],"source_qid":null,"duplicate_group_id":"exact-e0fd9ee659b9","duplicate_sources":[{"record_id":"0ce71c4b24959c22a68b","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":97,"source_qid":null},{"record_id":"15167f218cce4c22529c","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":179,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"0ce71c4b24959c22a68b","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":97,"supporting_pages":[97],"source_qid":null,"domain_hint":"Paediatrics","stem":"Tanya has brought her 2-year-old son to your clinic, disgruntled and annoyed by the child’s condition. She tells you that 2\nmonths ago, she started to wean the child onto solid foods and currently his diet includes breastfeeding 3 times a day 5\nminutes from each of her breasts and a bowl of cereal and rice every morning. The child has dropped from the 50\" to 25th\npercentile. The child’s past medical history is remarkable for one episode of admission due to bronchiolitis. Which one of\nthe following is the most likely cause of this baby’s diminished weight gain?","options":{"A":"A. Cystic fibrosis.","B":"B. Celiac disease.","C":"OC. Low calorie intake.","D":"D. Child abuse.","E":"E. Normal physiologic response to weaning."},"source_answer":"C","source_explanation":"With a drop in growth percentile, this child has developed failure to thrive.\nFailure to thrive is defined as either of the following:\n\n¢ Body mass index for age less than the 5th\n\n5th\n\npercentile\n\ne Length for age less than the percentile\n¢ Weight deceleration crossing two major percentile lines\n\n¢ Weight for age less than 50th percentile\n¢ Weight less than 75% of median weight for age\n¢ Weight less than 75% of median weight for length\n\n¢ Weight velocity less than the 5th percentile\n\nThe most common cause of failure to thrive is inadequate caloric intake. With 3 sessions of breast feeding and only one\nbowl of cereal, this baby is definitely receiving far less than his caloric needs and therefore, low caloric intake would be the\nmost likely cause of his problem.\n\n(Option A) With only one episode of bronchiolitis, the child is unlikely to have cystic fibrosis. Patients with cystic fibrosis\noften have respiratory infection recurrences.\n\n(Option B) Celiac disease can be a possibility, especially considering the fact that this child has been started on cereal and\nrice, both of which contain gluten, but celiac disease is far less common than inadequate calorie intake. Furthermore, the\nchild with celiac disease has more pronounced symptoms e.g., diarrhea.\n\n(Option D) Child abuse seems unlikely because firstly there is no comment in the question pointing towards the likelinood\nof child abuse and secondly, the mother seems concerned about her child’s condition and has sought medical care.\n\n(Option E) Normal physiologic response to weaning could be considered if the baby was receiving adequate nutrition.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"e0fd9ee659b93822649b0fa6c29b75c1293f551f","duplicate_group_id":"exact-e0fd9ee659b9","duplicate_sources":[{"record_id":"0ce71c4b24959c22a68b","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":97,"source_qid":null},{"record_id":"15167f218cce4c22529c","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":179,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
