INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f3201a9becdb3deb3ca8','Pediatric amedex 2025.pdf','98','Paediatrics','A previously healthy 18-month boy is brought to the Emergency Department with wheezing and cough starting 24 hours
ago. On examination, he has a respiratory rate of 35 breaths per minute. Bilateral wheeze is evident on chest
auscultation, as well as mildly diminished breath sounds of the left hemithorax. There is family history of asthma, as well
as allergy in history. Which one of the following is the most appropriate next step in management of this child?','{"A":"A. Nebulized salbutamol 4-hourly.","B":"B. Amoxicillin.","C":"OC. Admission and administration of oxygen.","D":"D. Chest physiotherapy.","E":"E. Chest X-ray (CXR)."}','C','Wheezing in children have a multitude of causes. The age of the child, physical findings, and the pattern and associations
can help narrow down the differential diagnoses.

For instance, wheezing associated with feeding points towards reflux disease as the most likely cause, while wheeze and
cough may suggest asthma. Positional wheeze, for example when the child is supine, is suggestive of laryngomalacia,
whereas, wheeze in the presence of fever may be due to infections. Sudden onset unilateral wheezing is a strong clue to
foreign body aspiration.

The age of onset is another important clue to the diagnosis. Early onset wheeze can reflect a congenital problem.
Bronchiolitis is a very common cause of wheezing in children younger than 12 months, and asthma is the most common
cause of episodic wheezing in children younger than 5 years. Depsite this, a definite diagnosis of asthma is avoided at
this age group and other terms suchs wheeze syndrom, viral wheeze, etc. are used instead.

In this child, wheezing and cough is of sudden onset, suggesting aspiration; however, bilaterality of the wheeze on exam
makes this diagnosis very unlikely. The presence of cough and the strong family history of asthma and allergy put asthma
at the top of the differential diagnoses list. This child though has also diminished breath sounds of the right lung that
mayu suggest collection either in the lung or pleural space. This child needs to be admitted and through investigation
carried out; however, making sure of adequate oxygenation regardless of the diagnosis comes first.

(Option A) Based on the provisional diagnosis of asthma, a trial of salbutamol is required both diagnostically and
therapeutically because adequate response to bronchodilators is in favor of a diagnosis of asthma. This should be
performed after oxygenation has started. Salbutamol is given by nebulizer in this age group. An adequate response to
therapy almost clinches the diagnosis with high certainty.

(Option B) Antibiotics such as amoxicillin may be necessary later on if investigations suggest bacterial infections such as
pneumonia.

(Option D) Chest physiotherapy is of little, if any, value at this point.

(Option E) CXR is indicated in children who present with unexplained wheezing that is unresponsive to bronchodilators or
with recurrent wheezing. It is not indicated in this child who has presented with first-time wheeze that is very likely to be
due to asthma. It, however, might be indicated if the wheeze is proved to be due to other causes than asthma, e.g.,
infections, foreign body, etc.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[98],"source_qid":null,"duplicate_group_id":"exact-a74f421a163c","duplicate_sources":[{"record_id":"f3201a9becdb3deb3ca8","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":98,"source_qid":null},{"record_id":"179a996c12cadf3f56f8","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":137,"source_qid":null},{"record_id":"f02ee6aaa81c5b9fe48d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1329,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"f3201a9becdb3deb3ca8","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":98,"supporting_pages":[98],"source_qid":null,"domain_hint":"Paediatrics","stem":"A previously healthy 18-month boy is brought to the Emergency Department with wheezing and cough starting 24 hours\nago. On examination, he has a respiratory rate of 35 breaths per minute. Bilateral wheeze is evident on chest\nauscultation, as well as mildly diminished breath sounds of the left hemithorax. There is family history of asthma, as well\nas allergy in history. Which one of the following is the most appropriate next step in management of this child?","options":{"A":"A. Nebulized salbutamol 4-hourly.","B":"B. Amoxicillin.","C":"OC. Admission and administration of oxygen.","D":"D. Chest physiotherapy.","E":"E. Chest X-ray (CXR)."},"source_answer":"C","source_explanation":"Wheezing in children have a multitude of causes. The age of the child, physical findings, and the pattern and associations\ncan help narrow down the differential diagnoses.\n\nFor instance, wheezing associated with feeding points towards reflux disease as the most likely cause, while wheeze and\ncough may suggest asthma. Positional wheeze, for example when the child is supine, is suggestive of laryngomalacia,\nwhereas, wheeze in the presence of fever may be due to infections. Sudden onset unilateral wheezing is a strong clue to\nforeign body aspiration.\n\nThe age of onset is another important clue to the diagnosis. Early onset wheeze can reflect a congenital problem.\nBronchiolitis is a very common cause of wheezing in children younger than 12 months, and asthma is the most common\ncause of episodic wheezing in children younger than 5 years. Depsite this, a definite diagnosis of asthma is avoided at\nthis age group and other terms suchs wheeze syndrom, viral wheeze, etc. are used instead.\n\nIn this child, wheezing and cough is of sudden onset, suggesting aspiration; however, bilaterality of the wheeze on exam\nmakes this diagnosis very unlikely. The presence of cough and the strong family history of asthma and allergy put asthma\nat the top of the differential diagnoses list. This child though has also diminished breath sounds of the right lung that\nmayu suggest collection either in the lung or pleural space. This child needs to be admitted and through investigation\ncarried out; however, making sure of adequate oxygenation regardless of the diagnosis comes first.\n\n(Option A) Based on the provisional diagnosis of asthma, a trial of salbutamol is required both diagnostically and\ntherapeutically because adequate response to bronchodilators is in favor of a diagnosis of asthma. This should be\nperformed after oxygenation has started. Salbutamol is given by nebulizer in this a