INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('6f99679007a7be9a1310','src-v294-5083b15f',NULL,'100','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','A 16-month-old child is brought to your attention by his parents because of their concerns about their child’s language delay. He was
born at 36 weeks through normal vaginal delivery with a birth weight of 2500 g. At 8 months of age, a ''mother and child health screening
test'' for hearing was performed that was completely normal. The parents say that he babbles but has not spoken any words so far. On
physical examination, the child appears quite normal. Which one of the following will you recommend?',NULL,'C','Parents are usually the first to be suspicious of their child having a hearing problem and they are almost always right. Concerns of
parents about possible developmental delays should never be ignored and have to be addressed promptly. In this child, the parents are
concerned about language delay.

Language delay is defined as either of the following:

¢ Late to talk and first words do not appear by the age of 15-18 months.

¢ The child gets their first words but then does not go on to develop new words quickly.

¢ By two years of age, the child is saying less than 50 words and is not using any two word combinations (e.g. ‘more drink’, ‘Daddy
gone’, ‘car go’).

¢ The child has difficulty understanding what is being said to them and has difficulties following instructions.

¢ The child’s language sounds immature for their age.

¢ Difficulties attending at group time at kindergarten or school.

¢ The very young child may have difficulties with eye contact, attending to activities and to speech and using sounds and gestures.

¢ Difficulty answering questions.

¢ Difficulty sequencing words together in sentences.

¢ Difficulty reading and writing.

¢ Difficulty getting their message across.

¢ Uses incorrect grammar (e.g., ‘me want that red one’ instead of ‘l want the red one’).

By the age of 2 years a child should be able to:

¢ Say first name
e¢ Say many words (mostly naming words)
¢ Begin to use one- to two-word sentences such as ‘want milk’

Not saying even a word by the age of 15-18 months is definitely an indicator of language delay for which investigation should follow.
This child is 16 months now; therefore, it is best to wait until 18 months of age to see if he can speak his first word. Sine hearing
problems are the most common cause of language delay, a formal audiometry assessment (option B) would be the most appropriate
option to consider if he fails to speak his first word by the age of 18 months.

(Option A) Parents cannot be reassured unless their child can speak his first word by the age of 18 months.

(Option D) As the name implies, UNNHS test is a screening test. Screening tests are to find asymptomatic cases. Since this child
seems to have hearing problems (symptomatic) repeating a test would be useless and formal audiological assessment is needed as the
most appropriate step in management. Several techniques are available for children who are still so young to engage in tests where
speaking is necessary.

(Option E) The hearing deficit as a possible cause of language delay may or may not be associated with dysmorphic features indicative
of a congenital developmental problem or syndrome. This does not change the necessity for confirmation of hearing deficit by
audiological assessments when indicated. This child still has until 18 months of age to say his word before language delay is even
considered.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[100],"source_qid":null,"duplicate_group_id":"exact-71902ff5e20b","duplicate_sources":[{"record_id":"6f99679007a7be9a1310","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":100,"source_qid":null},{"record_id":"78d0ff6ba81899fe0f50","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":186,"source_qid":null},{"record_id":"1108134b4fefaf011b74","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1289,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.current