INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4a56f0a96637bf09f48c','Pediatric amedex 2025.pdf','101','Paediatrics','Which one of the following is the most common cause of persistent cough in children?','{"A":"A. Post-viral cough.","B":"OB. Asthma.","C":"C. Post-pertussis.","D":"D. Gastro-esophageal reflux disease (GERD).","E":"E. Passive smoking."}','B','By duration, cough is defined as acute (<3 weeks), subacute (3-8 weeks) and chronic or persistent (>8 weeks).
Asthma is the most common cause of persistent (chronic) cough in children and the second most common
cause in adults (after chronic bronchitis).

Post-viral cough is the most common cause of acute and subacute (not chronic) cough in children.
Other causes of persistent cough in children are as follows:

¢ Persistent bacterial bronchitis

¢ Chronic suppurative lung disease and bronchiectasis

¢ Foreign body

¢ Gastro-esophageal reflux disease (GERD)

¢ Upper respiratory cough syndrome (formerly Known as postnasal drip syndrome)
¢ Post-pertussis cough

¢ Increased cough receptor sensitivity

¢ Habit (psychogenic) cough

¢ Otogenic cough','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[101],"source_qid":null,"duplicate_group_id":"exact-e10fffd193d5","duplicate_sources":[{"record_id":"4a56f0a96637bf09f48c","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":101,"source_qid":null},{"record_id":"d25c20132891573d509b","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":122,"source_qid":null},{"record_id":"61ce7aafac981ba2c7e2","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":123,"source_qid":null},{"record_id":"95b3507ee44b6565c0fc","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1310,"source_qid":"765"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"4a56f0a96637bf09f48c","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":101,"supporting_pages":[101],"source_qid":null,"domain_hint":"Paediatrics","stem":"Which one of the following is the most common cause of persistent cough in children?","options":{"A":"A. Post-viral cough.","B":"OB. Asthma.","C":"C. Post-pertussis.","D":"D. Gastro-esophageal reflux disease (GERD).","E":"E. Passive smoking."},"source_answer":"B","source_explanation":"By duration, cough is defined as acute (<3 weeks), subacute (3-8 weeks) and chronic or persistent (>8 wee