INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('4a56f0a96637bf09f48c','src-v294-5083b15f',NULL,'101','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','Which one of the following is the most common cause of persistent cough in children?',NULL,'B','By duration, cough is defined as acute (<3 weeks), subacute (3-8 weeks) and chronic or persistent (>8 weeks).
Asthma is the most common cause of persistent (chronic) cough in children and the second most common
cause in adults (after chronic bronchitis).

Post-viral cough is the most common cause of acute and subacute (not chronic) cough in children.
Other causes of persistent cough in children are as follows:

¢ Persistent bacterial bronchitis

¢ Chronic suppurative lung disease and bronchiectasis

¢ Foreign body

¢ Gastro-esophageal reflux disease (GERD)

¢ Upper respiratory cough syndrome (formerly Known as postnasal drip syndrome)
¢ Post-pertussis cough

¢ Increased cough receptor sensitivity

¢ Habit (psychogenic) cough

¢ Otogenic cough',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[101],"source_qid":null,"duplicate_group_id":"exact-e10fffd193d5","duplicate_sources":[{"record_id":"4a56f0a96637bf09f48c","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":101,"source_qid":null},{"record_id":"d25c20132891573d509b","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":122,"source_qid":null},{"record_id":"61ce7aafac981ba2c7e2","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":123,"source_qid":null},{"record_id":"95b3507ee44b6565c0fc","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1310,"source_qid":"765"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options