INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5348bb55a42a1ec40c27','Pediatric amedex 2025.pdf','102','Paediatrics','Which one of the following is the most common cause of painful rectal bleeding in children?','{"A":"A. Intussusception.","B":"B. Gastroenteritis.","C":"OC. Anal fissure.","D":"D. Meckel’s diverticulum.","E":"E. Hemorrhoids."}','C','Anal fissure is the most common cause of painful rectal bleeding in childhood. It is usually
caused by passage of hard stool associated with constipation. The common presentation is
bright blood on the surface of stool, on the nappy or toilet paper.

(Option A) Intussusception is associated with abdominal pain and rectal bleeding, not usually
with pain on defecation and not as common as anal fissure.

(Option B) Gastroenteritis and juvenile polyps are the most common causes of rectal bleeding
in children aged 2 to 5 years, but these conditions are not associated with painful defecation.

(Option D) Meckel''s diverticulum can cause blood in the stool and abdominal pain but the pain
is not related to defecation. Moreover, it is far less common than anal fissure.

(Option E) Hemorrhoids neither are associated with painful defecation, nor as common in
childhood.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[102],"source_qid":null,"duplicate_group_id":"exact-beb2511d3a1d","duplicate_sources":[{"record_id":"5348bb55a42a1ec40c27","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":102,"source_qid":null},{"record_id":"43851be736676a69ca9d","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":173,"source_qid":null},{"record_id":"be9850a77b4314e06fc1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1316,"source_qid":"904"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"5348bb55a42a1ec40c27","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":102,"supporting_pages":[102],"source_qid":null,"domain_hint":"Paediatrics","stem":"Which one of the following is the most common cause of painful rectal bleeding in children?","options":{"A":"A. Intussusception.","B":"B. Gastroenteritis.","C":"OC. Anal fissure.","D":"D. Meckel’s diverticulum.","E":"E. Hemorrhoids."},"source_answer":"C","source_explanation":"Anal fissure is the most common cause of painful rectal bleeding in childhood. It is usually\ncaused by passage of hard stool associated with constipation. The common presentation is\nbright blood on the surface of stool, on the nappy or toilet paper.\n\n(Option A) Intussusception is associated with abdominal pain and rectal bleeding, 