INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('04860ce55b1bd1d47034','Pediatric amedex 2025.pdf','103','Paediatrics','Which one of the following statements is correct about Perthes disease?','{"A":"A. Hip mobility is reduced especially abduction and external rotation.","B":"B. Ultrasound is the modality of choice to make a diagnosis.","C":"OC. Progress is evaluated with serial radiological examination.","D":"D. Osteotomy is the treatment of choice.","E":"E. The inflammatory markers such as WBC, ESR and CRP are usually raised."}','C','Legg-Calvé-Perthes disease, also called Perthes disease is avascular necrosis (AVN) of the proximal femoral head
resulting from compromise of blood supply to this area. Perthes disease usually occurs in children aged 2-12 years with a
peak incidence in children between 4 and 8 years. It is more common in boys than girls. The disease has an insidious
onset and may follow an injury to the hip. Perthes disease is unilateral in most cases (80% -90%), and in only 10%-20% of
cases both hips are involved. Even in bilateral cases, the hip joints are involved successively, not simultaneously.

Affected children often have delayed bone age, disproportionate growth, and a mildly shortened stature (smaller than
age). Perthes disease can be idiopathic, or it may result from a slipped capital femoral epiphysis, trauma, steroid use,
sickle-cell crisis, toxic synovitis, or congenital dislocation of the hip.

The earliest sign of Perthes disease is an intermittent limp, especially after exertion, with mild or intermittent pain in the
anterior part of the thigh.

NOTE- Perthes disease is the most common cause of a limp in the 4- to 10-year-old age group.

The classic presentation of Perthes disease has been described as a ‘painless limp’. The child may present with limited
range of motion of the affected extremity. The most common symptom is persistent pain.

Hip pain may develop and is a result of necrosis of the involved bone. This pain may be referred to the medial aspect of
the ipsilateral knee or to the lateral thigh. The quadriceps muscles and adjacent thigh soft tissues may atrophy, and the
hip may develop adduction flexion contracture. The patient may have an antalgic gait with limited hip motion, or a
Trendelenburg gate (abductor lurch). Pain may be present with passive range of motion and limited hip movement,
especially internal rotation and abduction.

Laboratory studies including a full blood count, ESR and CRP are usually normal and are often ordered to exclude other
possible causes of hip pain and limp such as septic arthritis, transient synovitis, or juvenile rheumatoid arthritis.

In most cases X-rays are normal early in the course of the disease but are used serially to assess the progression of the
disease. The following are radiographic stages of Perthes disease in time:

¢ Stage 1 - Cessation of femoral epiphyseal growth
¢ Stage 2 - Subchondral fracture

¢ Stage 3 - Resorption

¢ Stage 4 - Reossification

¢ Stage 5 - Healed or residual stage

These stages can take 12-40 months. A bone scan can be used to evaluate the site for avascular necrosis (AVN).','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[103],"source_qid":null,"duplicate_group_id":"exact-663559678266","duplicate_sources":[{"record_id":"04860ce55b1bd1d47034","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":103,"source_qid":null},{"record_id":"4a90fe3b50af0cf13a10","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":83,"source_qid":null},{"record_id":"123c7b4d486974dabb68","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":84,"source_qid":null},{"record_id":"a55399ed3a47ae3ea1bf","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1379,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"04860ce55b1bd1d47034","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":103,"supporting_pages":[103],"source_qid":null,"domain_hint":"Paediatrics","stem":"Which one of the following statements is correct about Perthes disease?","options":{"A":"A. Hip mobility is reduced especially abduction and external rotation.","B":"B. Ultrasound is the modality of choice to make a diagnosis.","C":"OC. Progress is evaluated with serial radiological examination.","D":"D. Osteotomy is the treatment of choice.","E":"E. The inflammatory markers such as WBC, ESR and CRP are usually raised."},"source_answer":"C","source_explanation":"Legg-Calvé-Perthes disease, also called Perthes disease is avascular necrosis (AVN) of the proximal femoral head\nresulting from compromise of blood supply to this area. Perthes disease usually occurs in children aged 2-12 years with a\npeak incidence in children between 4 and 8 years. It is more common in boys than girls. The disease has an insidious\nonset and may follow an injury to the hip. Perthes disease is unilateral in most cases (80% -90%), and in only 10%-20% of\ncases both hips are involved. Even in bilateral cases, the hip joints are involved successively, not simultaneously.\n\nAffected children often have delayed bone age, disproportionate growth, and a mildly shortened stature (smaller than\nage). Perthes disease can be idiopathic, or it may result from a slipped capital femoral epiphysis, trauma, steroid use,\nsickle-cell crisis, toxic synovitis, or congenital dislocation of the hip.\n\nThe earliest sign of Perthes disease is an intermittent limp, especially after exertion, with mild or intermittent pain in the\nanterior part of the thigh.\n\nNOTE- Perthes disease is the most common cause of a limp in the 4- to 10-year-old age group.\n\nThe classic presentation of Perthes disease has been described as a ‘painless limp’. The child may present with limited\nrange of motion of the affected extremity. The most common symptom is persistent pain.\n\nHip pain may develop and is a result of necrosis of the involved bone. This pain may be referred to the medial aspect of\nthe ipsilateral knee or to the lateral thigh. The quadriceps muscles and adjacent thigh soft tissues may atrophy, and the\nhip may develop adduction flexion contracture. The patient may have an antalgic gait with limited hip motion, or a\nTrendelenburg gate (abductor lurch). Pain may be present with passive range of motion and limited hip movement,\nespecially internal rotation and abduction.\n\nLaboratory studies including a full blood count, ESR and CRP are usually normal and are often ordered to exclude other\npossible causes of hip pain and limp such as septic arthritis, transient synovitis, or juvenile rheumatoid arthritis.\n\nIn most cases X-rays are normal early in the course of the disease but are used serially to assess the progression of the\ndisease. The following are radiographic stages of Perthes disease in time:\n\n¢ Stage 1 - Cessation of femoral epiphyseal growth\n¢ Stage 2 - Subchondral fracture\n\n¢ Stage 3 - Resorption\n\n¢ Stage 4 - Reossification\n\n¢ Stage 5 - Healed or residual stage\n\nThese stages can take 12-40 months. A bone scan can be used to evaluate the site for avascular necrosis (AVN).","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"6635596782662c79590d63c33d02231d3c973ec2","duplicate_group_id":"exact-663559678266","duplicate_sources":[{"record_id":"04860ce55b1bd1d47034","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":103,"source_qid":null},{"record_id":"4a90fe3b50af0cf13a10","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":83,"source_qid":null},{"record_id":"123c7b4d486974dabb68","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":84,"source_qid":null},{"record_id":"a55399ed3a47ae3ea1bf","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1379,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
