INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('04860ce55b1bd1d47034','src-v294-5083b15f',NULL,'103','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','Which one of the following statements is correct about Perthes disease?',NULL,'C','Legg-Calvé-Perthes disease, also called Perthes disease is avascular necrosis (AVN) of the proximal femoral head
resulting from compromise of blood supply to this area. Perthes disease usually occurs in children aged 2-12 years with a
peak incidence in children between 4 and 8 years. It is more common in boys than girls. The disease has an insidious
onset and may follow an injury to the hip. Perthes disease is unilateral in most cases (80% -90%), and in only 10%-20% of
cases both hips are involved. Even in bilateral cases, the hip joints are involved successively, not simultaneously.

Affected children often have delayed bone age, disproportionate growth, and a mildly shortened stature (smaller than
age). Perthes disease can be idiopathic, or it may result from a slipped capital femoral epiphysis, trauma, steroid use,
sickle-cell crisis, toxic synovitis, or congenital dislocation of the hip.

The earliest sign of Perthes disease is an intermittent limp, especially after exertion, with mild or intermittent pain in the
anterior part of the thigh.

NOTE- Perthes disease is the most common cause of a limp in the 4- to 10-year-old age group.

The classic presentation of Perthes disease has been described as a ‘painless limp’. The child may present with limited
range of motion of the affected extremity. The most common symptom is persistent pain.

Hip pain may develop and is a result of necrosis of the involved bone. This pain may be referred to the medial aspect of
the ipsilateral knee or to the lateral thigh. The quadriceps muscles and adjacent thigh soft tissues may atrophy, and the
hip may develop adduction flexion contracture. The patient may have an antalgic gait with limited hip motion, or a
Trendelenburg gate (abductor lurch). Pain may be present with passive range of motion and limited hip movement,
especially internal rotation and abduction.

Laboratory studies including a full blood count, ESR and CRP are usually normal and are often ordered to exclude other
possible causes of hip pain and limp such as septic arthritis, transient synovitis, or juvenile rheumatoid arthritis.

In most cases X-rays are normal early in the course of the disease but are used serially to assess the progression of the
disease. The following are radiographic stages of Perthes disease in time:

¢ Stage 1 - Cessation of femoral epiphyseal growth
¢ Stage 2 - Subchondral fracture

¢ Stage 3 - Resorption

¢ Stage 4 - Reossification

¢ Stage 5 - Healed or residual stage

These stages can take 12-40 months. A bone scan can be used to evaluate the site for avascular necrosis (AVN).',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[103],"source_qid":null,"duplicate_group_id":"exact-663559678266","duplicate_sources":[{"record_id":"04860ce55b1bd1d47034","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":103,"source_qid":null},{"record_id":"4a90fe3b50af0cf13a10","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":83,"source_qid":null},{"record_id":"123c7b4d486974dabb68","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":84,"source_qid":null},{"record_id":"a55399ed3a47ae3ea1bf","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1379,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=exclu