INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('bcfb3f670c82405caf2b','Pediatric amedex 2025.pdf','105','Paediatrics','A 4-year-old girl is brought to you by her kindergarten teacher. She states that the child has not been
well since this morning, vomited once, and complained of central abdominal pain. On examination,
the child looks unwell and has a temperature of 39°C. Which one of the following would be most
expected in this child?','{"A":"OA. Numerous pus cells on urine microscopy.","B":"B. Inflamed ear drums.","C":"C. Neck stiffness.","D":"D. Inflamed tonsils.","E":"E. Localized tenderness over the right iliac fossa."}','A','It is not uncommon for young children to have a urinary tract infection (UTI) without classic urinary
symptoms of urgency, frequency, and/or dysuria. In fact, the younger the child, the more likely the
symptoms are vague and nonspecific. If the cause of such presentation is a UTI, abnormally high
counts of white blood cells (puss cells) are the most common and expected finding on urinalysis.

(Option B) Inflamed ear drums are seen in otitis media. Otitis media is not associated with
abdominal pain; therefore, not a likely diagnosis with this constellation of symptoms.

(Option C) Neck stiffness could be elicited in meningitis. Fever and unwellness are expected
features, but abdominal pain is less likely.

(Option D) Tonsillitis can make a child ill and febrile but does not cause abdominal pain.

(Option E) Appendicitis can cause Central abdominal pain, vomiting, and localized tenderness over
the right iliac fossa. However, it is uncommon for appendicitis to cause a fever as high as 39°C
unless it is complicated by perforation. Since the symptoms began this morning, perforation of
appendicitis would not be expected. It is unusual for an appendicitis to perforate this early.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[105],"source_qid":null,"duplicate_group_id":"exact-5d3d117463f8","duplicate_sources":[{"record_id":"bcfb3f670c82405caf2b","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":105,"source_qid":null},{"record_id":"4be9cd274ff2e2239cc8","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":95,"source_qid":null},{"record_id":"404ad97247701cd23c6f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1358,"source_qid":"115"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"bcfb3f670c82405caf2b","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":105,"supporting_pages":[105],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 4-year-old girl is brought to you by her kindergarten teacher. She states that the child has not been\nwell since this morning, vomited once, and complained of central abdominal pain. On examination,\nthe child looks unwell and has a temperature of 39°C. Which one of the following would be most\nexpected in this child?","options":{"A":"OA. Numerous pus cells on urine microscopy.","B":"B. Inflamed ear drums.","C":"C. Neck stiffness.","D":"D. Inflamed tonsils.","E":"E. Localized tenderness over the right iliac fossa."},"source_answer":"A","source_explanation":"It is not uncommon for young children to have a urinary tract infection (UTI) without classic urinary\nsymptoms of urgency, frequency, and/or dysuria. In fact, the younger the child, the more likely the\nsymptoms are vague and nonspecific. If the cause of such presentation is a UTI, abnormally high\ncounts of white blood cells (puss cells) are the most common and expected finding on urinalysis.\n\n(Option B) Inflamed ear drums are seen in otitis media. Otitis media is not associated with\nabdominal pain; therefore, not a likely diagnosis with this constellation of symptoms.\n\n(Option C) Neck stiffness could be elicited in meningitis. Fever and unwellness are expected\nfeatures, but abdominal pain is less likely.\n\n(Option D) Tonsillitis can make a child ill and febrile but does not cause abdominal pain.\n\n(Option E) Appendicitis can cause Central abdominal pain, vomiting, and localized tenderness over\nthe right iliac fossa. However, it is uncommon for appendicitis to cause a fever as high as 39°C\nunless it is complicated by perforation. Since the symptoms began this morning, perforation of\nappendicitis would not be expected. It is unusual for an appendicitis to perforate this early.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"5d3d117463f8586d79a32c82bd68ae23a643a004","duplicate_group_id":"exact-5d3d117463f8","duplicate_sources":[{"record_id":"bcfb3f670c82405caf2b","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":105,"source_qid":null},{"record_id":"4be9cd274ff2