INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3e315bfc7ff0e57d806b','Pediatric amedex 2025.pdf','106','Paediatrics','A 6-month-old male infant was brought to your clinic with a characteristic pertussis cough. Which of the following is the best advice
for the patient’s parents to reduce their risk of infection?','{"A":"Commence a 3-dose pertussis revaccination.","B":"OB. Immediate booster immunizations against pertussis.","C":"A 5-day course of azithromycin.","D":"No action is required.","E":"Immediate immunization with pertussis immunoglobulin."}','B','Pertussis is a respiratory infection caused by Bordetella pertussis. The disease often has an incubation period of 7 to 10 days. In
unvaccinated individuals, Bordetella pertussis is highly infectious; spreading by aerosols to 90% of susceptible household
contacts.
Antibiotics, if given early during the paroxysmal and catarrhal stages, will ameliorate the symptoms. However, more patients do not
present at this stage and come to medical attention when the disease has been established. At this point, the role of antibiotics is
limited to preventing the disease from spreading to the patient''s contacts. It should be remembered that patients are rarely
infectious after three weeks.
Patients should be advised to avoid contact with others until five days after starting antibiotics. The antibiotics used in pertussis for
prevention of the disease spread for index case are:

e (First-line) Azithromycin 500 mg (child six months or older: 10 mg/kg up to 500 mg) orally for the first dose, then 250 mg
(child six months or older: 5 mg/kg up to 250 mg) orally, daily for a further four days (neonate and child younger than six
months: 10 mg/kg orally, daily for five days)

OR

e (First-line) Trimethoprim + sulfamethoxazole 160+800 mg (child 1 month or older: 4+20 mg/kg up to 160+800 mg) orally, 12-
hourly for 7 days
OR

¢ (Second-line) Clarithromycin 500 mg (child: 7.5 mg/kg up to 500 mg) orally, 12-hourly for seven days

NOTE - There is no clinical evidence to support roxithromycin for the treatment of pertussis
regarding prophylactic measures, the following guidelines are currently in place:','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-9e5a5c173aa7","duplicate_sources":[{"record_id":"3e315bfc7ff0e57d806b","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":106,"source_qid":null},{"record_id":"419cacb5f45a369cf9ad","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":53,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','high','{"record_id":"3e315bfc7ff0e57d806b","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":106,"source_qid":null,"domain_hint":"Paediatrics","stem":"A 6-month-old male infant was brought to your clinic with a characteristic pertussis cough. Which of the following is the best advice\nfor the patient’s parents to reduce their risk of infection?","options":{"A":"Commence a 3-dose pertussis revaccination.","B":"OB. Immediate booster immunizations against pertussis.","C":"A 5-day course of azithromycin.","D":"No action is required.","E":"Immediate immunization with pertussis immunoglobulin."},"source_answer":"B","source_explanation":"Pertussis is a respiratory infection caused by Bordetella pertussis. The disease often has an incubation period of 7 to 10 days. In\nunvaccinated individuals, Bordetella pertussis is highly infectious; spreading by aerosols to 90% of susceptible household\ncontacts.\nAntibiotics, if given early during the paroxysmal and catarrhal stages, will ameliorate the symptoms. However, more patients do not\npresent at this stage and come to medical attention when the disease has been established. At this point, the role of antibiotics is\nlimited to preventing the disease from spreading to the patient''s contacts. It should be remembered that patients are rarely\ninfectious after three weeks.\nPatients should be advised to avoid contact with others until five days after starting antibiotics. The antibiotics used in pertussis for\nprevention of the disease spread for index case are:\n\ne (First-line) Azithromycin 500 mg (child six months or older: 10 mg/kg up to 500 mg) orally for the first dose, then 250 mg\n(child six months or older: 5 mg/kg up to 250 mg) orally, daily for a further four days (neonate and child younger than six\nmonths: 10 mg/kg orally, daily for five days)\n\nOR\n\ne (First-line) Trimethoprim + sulfamethoxazole 160+800 mg (child 1 month or older: 4+20 mg/kg up to 160+800 mg) orally, 12-\nhourly for 7 days\nOR\n\n¢ (Second-line) Clarithromycin 500 mg (child: 7.5 mg/kg up to 500 mg) orally, 12-hourly for seven days\n\nNOTE - There is no clinical evidence to support roxithromycin for the treatment of pertussis\nregarding prophylactic measures, the following guidelines are currently in place:","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","dose","guideline","prophyl","treatment","vaccin"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","stem_hash":"9e5a5c173aa7261868464986eb79789aef745044","duplicate_group_id":"exact-9e5a5c173aa7","duplicate_sources":[{"record_id":"3e315bfc7ff0e57