INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('fc7c608464044e944c57','src-v294-5083b15f',NULL,'108','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','A 6-month-old boy is brought to your office by his mother with persistence bouts of cough for the past 2 weeks. Every bout of
cough is associated with cyanosis of the face and usually followed by vomiting. Which one of the following is the next step in
management?',NULL,'E','The clinical picture suggests respiratory infection with Bordetella pertussis.

Pertussis (whooping cough) is a bacterial respiratory infection caused by the organism, Bordetella pertussis (a Gram negative
bacillus). It is highly infectious and is spread by respiratory droplets to 70—100% of susceptible household contacts and 50-80% of
susceptible school contacts. Pertussis infection occurs worldwide, it affects all age groups, and is most serious in young,
unprotected infants. It commonly occurs in teenagers and young adults who have not been immunized or with waning immunity.
Patients are infectious just before, and for 21 days after, the onset of cough if left untreated.

lf treated early with antibiotics, the period of infectivity usually lasts 5 days or less after the commencement of therapy. Maternal
antibody does not give adequate protection against pertussis; therefore, babies can be infected before being immunized.

Pertussis presents with mild upper respiratory tract symptoms (catarrhal stage) and can progress to severe paroxysms of cough
(paroxysmal stage), often with a characteristic inspiratory whoop, followed by vomiting. Fever is usually absent or minimal.
Symptoms gradually resolve (convalescent stage). The paroxysmal cough and inspiratory whoop may be absent, particularly in
infants less than 6 months of age and in adults. Mild illness is common, particularly in immunized individuals. The cough may
persist for up to 3 months.

The indications for hospitalization/pediatric consultation include the following:

e Infants less than 6 months of age
e Any child who has had apnea, cyanosis, pneumonia, or encephalopathy as a complication of pertussis.

With cyanosis following the attacks of cough, this child needs to be admitted to the hospital as the most important next step in
management.

(Option A) Nasopharyngeal aspirate can be considered later, if indicated, after the child is admitted to the hospital.

(Option B) Immunization, at a later date, should be encouraged even if the child has had pertussis, but this step is not a part of
acute management plan.

(Option C) Antibiotics should be considered if:

e The patient is diagnosed in catarrhal or early paroxysmal phase (may reduce severity)
e Cough for less than 14 days (may reduce spread - reduces school exclusion period)

e Admitted to hospital

e There are complications (pneumonia, cyanosis, apnea)

Antibiotics of choice are azithromycin or clarithromycin. They can be used after the child is admitted to the hospital.
(Option D) Salbutamol or other bronchodilators has not been shown to be helpful in management of patients with pertussis.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-ed6573075dc2","duplicate_sources":[{"record_id":"fc7c608464044e944c57","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":108,"source_qid":null},{"record_id":"6a0598c81a911be06dec","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":135,"source_qid":null},{"record_id":"545553cafb9f9ae76180","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":136,"source_qid":null},{"record_id":"854c6280732c269d8be2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1293,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=exclude