INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f8c984973596969df350','Pediatric amedex 2025.pdf','109','Paediatrics','Kim, 3 years old, is brought to the Emergency Department by her parents reporting that their daughter is not feeling well at all. According to them, she developed a fever this morning and
started to refuse food and crying and throwing it out when she was fed. A short while later she became miserable and inconsolable, started drooling, and her breath became noisy. On
examination, she has a pulse rate of 140 bpm, respiratory rate of 34 breaths per minute with expiratory stridor, and a fever of 39.1°C. She maintains her neck extended. Lungs are clear on
auscultation. Which one of the following could be the most likely diagnosis?','{"A":"Croup.","B":"B. Acute bronchiolitis.","C":"C. Retropharyngeal abscess.","D":"OD. Acute epiglottitis.","E":"E. Bacterial pharyngitis."}','D','The given clinical picture is very suggestive of acute epiglottitis as the most likely diagnosis.

Epiglottitis is an acute inflammation in the supraglottic region of the oropharynx with inflammation of the epiglottis, vallecula, arytenoids, and aryepiglottic folds. Acute epiglottitis affects all
age groups. In children it is more common between ages 2 and 4 years; however, introduction of Hemophilus Influenza vaccine has resulted in a significant decline in incidence of the
condition in children. The condition is not as common in children anymore.

Epiglottitis often has a short course of progression and presents with high fever, sore throat, dysphagia/odynophagia, and drooling due to inability to swallow the saliva because swallowing
is painful and difficult. The child is miserable and often adopts a tripod position with a hyperextended neck to maintain the airway open. Muffled voice (hot potato voice), as if the patient is
struggling with a mouthful of hot food, is another feature seen in epiglottitis. Lungs are clear on auscultation but later as the condition escalates, expiratory stridor develops which is an
ominous sign.

How the tripod position maintains the airway patent

(Option A) Croup is the inflammation of larynx with or without involvement of the trachea and bronchi. The condition is caused by viruses with the RSV virus being the most common
etiology. Children with croup present with a typical seal barking cough and inspiratory stridor. Fever is often minimal or absent. There is no drooling, dysphagia, odynophagia. There is
usually a preceding viral prodrome including runny nose and sneezing. Lungs are clear on auscultation unless more distal airways are involved as well.

(Option B) Bronchiolitis, as the name implies, is the inflammation of bronchiole by viral respiratory infections. It is usually seen in infants younger than 12 months, and present with cough,
tachypnea, chest retraction, and widespread wheeze and crackles on lung auscultation.

(Option C) Retropharyngeal abscess has a similar presentation to epiglottitis; however, the rapid onset of symptoms in the absence a preceding bacterial upper respiratory tract infection
makes retropharyngeal abscess a far less likely diagnosis.

(Option E) Although bacterial pharyngitis can have a rapid course similar to epiglottitis, there are differences in presentation. Sore throat is a shared feature but acute pharyngitis does not
cause the tripod position, hyperextension of the neck, and expiratory stridor. There might be refusal of food due to the sore throat but drooling is rarely seen in acute pharyngitis.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[109],"source_qid":null,"duplicate_group_id":"exact-48519d888a7a","duplicate_sources":[{"record_id":"f8c984973596969df350","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":109,"source_qid":null},{"record_id":"e6b94516332baac22513","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":74,"source_qid":null},{"record_id":"c05310ef8d71becf6fa7","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1387,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"f8c984973596969df350","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":109,"supporting_pages":[109],"source_qid":null,"domain_hint":"Paediatrics","stem":"Kim, 3 years old, is brought to the Emergency Department by her parents reporting that their daughter is not feeling well at all. According to them, she developed a fever this morning and\nstarted to refuse food and crying and throwing it out when she was fed. A short while later she became miserable and inconsolable, started drooling, and her breath became noisy. On\nexamination, she has a pulse rate of 140 bpm, respiratory rate of 34 breaths per minute with expiratory stridor, and a fever of 39.1°C. She maintains her neck extended. Lungs are clear on\nauscultation. Which one of the following could be the most likely diagnosis?","options":{"A":"Croup.","B":"B. Acute bronchiolitis.","C":"C. Retropharyngeal abscess.","D":"OD. Acute epiglottitis.","E":"E. Bacterial pharyngitis."},"source_answer":"D","source_explanation":"The given clinical picture is very suggestive of acute epiglottitis as the most likely diagnosis.\n\nEpiglottitis is an acute inflammation in the supraglottic region of the oropharynx with inflammation of the epiglottis, vallecula, arytenoids, and aryepiglottic folds. Acute epiglottitis affects all\nage groups. In children it is more common between ages 2 and 4 years; however, introduction of Hemophilus Influenza vaccine has resulted in a significant decline in incidence of the\ncondition in children. The condition is not as common in children anymore.\n\nEpiglottitis often has a short course of progression and presents with high fever, sore throat, dysphagia/odynophagia, and drooling due to inability to swallow the saliva because swallowing\nis painful and difficult. The child is miserable and often adopts a tripod position with a hyperextended neck to maintain the airway open. Muffled voice (hot potato voice), as if the patient is\nstruggling with a mouthful of hot food, is another feature seen in epiglottitis. Lungs are clear on auscultation but later as the condition escalates, expiratory stridor develops which is an\nominous sign.\n\nHow the tripod position maintains the airway patent\n\n(Option A) Croup is the inflammation of larynx with or without involvement of the trachea and bronchi. The condition is caused by viruses with the RSV virus being the most common\netiology. Children with croup present with a typical seal barking cough and inspiratory stridor. Fever is often minimal or absent. There is no drooling, dysphagia, odynophagia. There is\nusually a preceding viral prodrome including runny nose and sneezing. Lungs are clear on auscultation unless more distal airways are involved as well.\n\n(Option B) Bronchiolitis, as the name implies, is the inflammation of bronchiole by viral respiratory infections. It is usually seen in infants younger than 12 months, and present with cough,\ntachypnea, chest retraction, and widespread wheeze and crackles on lung auscultation.\n\n(Option C) Retropharyngeal abscess has a similar presentation to epiglottitis; however, the rapid onset of symptoms in the absence a preceding bacterial upper respiratory tract infection\nmakes retropharyngeal abscess a far less likely diagnosis.\n\n(Option E) Although bacterial pharyngitis can have a rapid course similar to epiglottitis, there are differences in presentation. Sore throat is a shared feature but acute pharyngitis does not\ncause the tripod position, hyperextension of the neck, and expiratory stridor. There might be refusal of food due to the sore throat but drooling is rarely seen in acute pharyngitis.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","vaccin"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"48519d888a7aa66ade93cfdf57f0dfb253c90028","duplicate_group_id":"exact-48519d888a7a","duplicate_sources":[{"record_id":"f8c984973596969df350","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":109,"source_qid":null},{"record_id":"e6b94516332baac22513","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":74,"source_qid":null},{"record_id":"c05310ef8d71becf6fa7","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1387,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
