INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('f8c984973596969df350','src-v294-5083b15f',NULL,'109','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','Kim, 3 years old, is brought to the Emergency Department by her parents reporting that their daughter is not feeling well at all. According to them, she developed a fever this morning and
started to refuse food and crying and throwing it out when she was fed. A short while later she became miserable and inconsolable, started drooling, and her breath became noisy. On
examination, she has a pulse rate of 140 bpm, respiratory rate of 34 breaths per minute with expiratory stridor, and a fever of 39.1°C. She maintains her neck extended. Lungs are clear on
auscultation. Which one of the following could be the most likely diagnosis?',NULL,'D','The given clinical picture is very suggestive of acute epiglottitis as the most likely diagnosis.

Epiglottitis is an acute inflammation in the supraglottic region of the oropharynx with inflammation of the epiglottis, vallecula, arytenoids, and aryepiglottic folds. Acute epiglottitis affects all
age groups. In children it is more common between ages 2 and 4 years; however, introduction of Hemophilus Influenza vaccine has resulted in a significant decline in incidence of the
condition in children. The condition is not as common in children anymore.

Epiglottitis often has a short course of progression and presents with high fever, sore throat, dysphagia/odynophagia, and drooling due to inability to swallow the saliva because swallowing
is painful and difficult. The child is miserable and often adopts a tripod position with a hyperextended neck to maintain the airway open. Muffled voice (hot potato voice), as if the patient is
struggling with a mouthful of hot food, is another feature seen in epiglottitis. Lungs are clear on auscultation but later as the condition escalates, expiratory stridor develops which is an
ominous sign.

How the tripod position maintains the airway patent

(Option A) Croup is the inflammation of larynx with or without involvement of the trachea and bronchi. The condition is caused by viruses with the RSV virus being the most common
etiology. Children with croup present with a typical seal barking cough and inspiratory stridor. Fever is often minimal or absent. There is no drooling, dysphagia, odynophagia. There is
usually a preceding viral prodrome including runny nose and sneezing. Lungs are clear on auscultation unless more distal airways are involved as well.

(Option B) Bronchiolitis, as the name implies, is the inflammation of bronchiole by viral respiratory infections. It is usually seen in infants younger than 12 months, and present with cough,
tachypnea, chest retraction, and widespread wheeze and crackles on lung auscultation.

(Option C) Retropharyngeal abscess has a similar presentation to epiglottitis; however, the rapid onset of symptoms in the absence a preceding bacterial upper respiratory tract infection
makes retropharyngeal abscess a far less likely diagnosis.

(Option E) Although bacterial pharyngitis can have a rapid course similar to epiglottitis, there are differences in presentation. Sore throat is a shared feature but acute pharyngitis does not
cause the tripod position, hyperextension of the neck, and expiratory stridor. There might be refusal of food due to the sore throat but drooling is rarely seen in acute pharyngitis.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[109],"source_qid":null,"duplicate_group_id":"exact-48519d888a7a","duplicate_sources":[{"record_id":"f8c984973596969df350","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":109,"source_qid":null},{"record_id":"e6b94516332baac22513","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":74,"source_qid":null},{"record_id":"c05310ef8d71becf6fa7","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1387,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,curren