INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f957338b4f5adbcc7298','Pediatric amedex 2025.pdf','110','Paediatrics','Tom, five years old, is in the emergency department with a swollen face, ankles, and a distended abdomen. Dipstick urine is
positive for blood (trace) and protein (+++). He is hemodynamically stable. Which one of the following is the most appropriate next
investigation to consider for him?','{"A":"A. Urine culture.","B":"OB. Urinary protein to creatinine Ratio.","C":"C. Urine cytology.","D":"D. Blood chemistry.","E":"E. Renal ultrasound."}','B','With proteinuria and edema, Tom must be fully assessed for renal disease and probably nephrotic syndrome.

Proteinuria is likely to present as a symptomatic disease (e.g., nephrotic syndrome), an incidental finding during an assessment of
renal or nonrenal symptoms, or detected on urinary screening in asymptomatic patients.

Nephrotic syndrome is defined by generalized edema, heavy proteinuria (+++ or ++++ on dipstick), hypoalbuminemia, and
hypercholesterolemia. It occurs most commonly in young children, with the peak incidence for the initial episode at 2 years of age.

Children with steroid-responsive nephrotic syndrome usually have no nephritic features such as hematuria, hypertension, or raised
serum creatinine. However, microscopic hematuria is occasionally seen (15-30%).

Most children will develop minimal change disease (80%) or focal segmental GN (5—10%), while mesangial proliferative
glomerulonephritis (GN), membranoproliferative GN, and membranous GN are rare.

In as many as 30-50% of children, proteinuria is transient and resolves over 1—2 weeks. Transient proteinuria is common during
febrile illnesses and can occur with strenuous exercise, emotional stress, and following seizures or abdominal surgery.

Isolated proteinuria resolves spontaneously after the cessation of the causal factor and an extensive workup is not necessary.
Isolated proteinuria is common in children while persistent proteinuria is much less common.

Evaluation of proteinuria should begin with a careful history and thorough physical examination, urine microscopic examination,
and determination of the amount of protein excretion rate (PER). The PER has been traditionally measured using 24-hour urine
collections. However, the collection of 24-hour urine is often cumbersome, and spot urinary protein-to-creatinine ratio (PCR),
expressed in g/g or mg/mg, has become a simple and attractive yet reliable alternative. A spot urine PCR has been found to have
a significant linear correlation with a 24-hour urine PCR. because the PCR compares urinary protein concentration with urinary
creatinine concentration, urinary dilution or concentration does not influence this value.

Accurately timed collections are difficult to obtain in young children, and the protein/creatinine ratio (PCR) on an untimed urine
specimen has been the accepted standard for many years. A random urine specimen is acceptable.

(Option A) Urine microscopy and culture (Urine MCS) is considered if the patient is febrile

(Option C) Urine cytology is considered when the glomerular or non-glomerular origin or under debate and the presence of urinary
casts provides a clue

(Options D & E) Blood chemistry and renal ultrasound are considered the next steps in order to look for an underlying disease but
not the next step.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[110],"source_qid":null,"duplicate_group_id":"exact-6fc93c1e6ab4","duplicate_sources":[{"record_id":"f957338b4f5adbcc7298","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":110,"source_qid":null},{"record_id":"06f1f64715ef22ed722c","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":34,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"f957338b4f5adbcc7298","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":110,"supporting_pages":[110],"source_qid":null,"domain_hint":"Paediatrics","stem":"Tom, five years old, is in the emergency department with a swollen face, ankles, and a distended abdomen. Dipstick urine is\npositive for blood (trace) and protein (+++). He is hemodynamically stable. Which one of the following is the most appropriate next\ninvestigation to consider for him?","options":{"A":"A. Urine culture.","B":"OB. Urinary protein to creatinine Ratio.","C":"C. Urine cytology.","D":"D. Blood chemistry.","E":"E. Renal ultrasound."},"source_answer":"B","source_explanation":"With proteinuria and edema, Tom must be fully assessed for renal disease and probably nephrotic syndrome.\n\nProteinuria is likely to present as a symptomatic disease (e.g., nephrotic syndrome), an incidental finding during an assessment of\nrenal or nonrenal symptoms, or detected on urinary screening in asymptomat