INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b115d96c09d0f436ddeb','Pediatric amedex 2025.pdf','111','Paediatrics','A 2-month-old infant is brought to the pediatric clinic with concerns of frequent regurgitation and irritability after feeding.
The parents report that the baby often arches his back during feeds and has trouble sleeping. Physical examination
reveals a healthy-appearing infant with no signs of dehydration. Which of the following is the most appropriate next step
in management?','{"A":"A. Start proton pump inhibitor therapy.","B":"B. Recommend thickened feeds.","C":"C. Refer to a pediatric gastroenterologist.","D":"OD. Advise the parents to hold the baby upright after feeds.","E":"E. Perform an upper gastrointestinal series."}','D','The infant described in the scenario is exhibiting typical signs of gastro-oesophageal reflux (GOR), including frequent
regurgitation, irritability after feeding, arching of the back, and difficulty sleeping. This is a common issue in infants,
particularly at two months of age, and is typically self-limiting as the baby matures. GOR in infants can cause
discomfort, but it does not usually lead to serious complications in healthy, thriving babies without signs of severe
distress or dehydration.

Advise the parents to hold the baby upright after feeds

This is a key recommendation for managing mild GOR in infants. Holding the baby upright for 20 to 30 minutes after
feeding can help minimise reflux and may reduce symptoms like irritability and regurgitation. Other conservative
measures include:

¢ Smaller, more frequent feedings to reduce the volume in the stomach.

¢ Burping frequently during feeds to prevent air swallowing.

¢ Placing the infant on their back to sleep but avoiding excessive positioning changes (such as placing them on their
stomach).

(Option A) Proton pump inhibitors (PPIs) are typically used for more severe or complicated reflux, especially when
there is concern for esophagitis or when GOR is not adequately managed by non-pharmacological means. Since the
infant here is healthy-appearing and the symptoms are typical for mild GOR, PPIs are not indicated.

(Option B) Thickening feeds is sometimes used for infants with significant reflux symptoms to help reduce regurgitation.
However, thickened feeds may not be necessary in many cases of mild GOR and can be challenging to implement,
particularly for breastfeeding infants. While it may be considered if symptoms persist or worsen, it is not the first-line
intervention.

(Option C) Referral to a specialist is typically reserved for cases with more severe symptoms, failure to thrive, or
concerns about complications (e.g. esophagitis, aspiration). In this case, the infant appears healthy, and there are no
signs of complications.

(Option E) An upper gastrointestinal series (barium swallow) is typically reserved for cases where structural
abnormalities are concerned, or the diagnosis is uncertain (e.g. when other gastrointestinal conditions are suspected). It
is not needed for typical cases of GOR in healthy infants.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[111],"source_qid":null,"duplicate_group_id":"exact-ba8f94181c5e","duplicate_sources":[{"record_id":"b115d96c09d0f436ddeb","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":111,"source_qid":null},{"record_id":"b56f5e58af36921a1b62","record_type":"visual_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":105,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"b115d96c09d0f436ddeb","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":111,"supporting_pages":[111],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 2-month-old infant is brought to the pediatric clinic with concerns of frequent regurgitation and irritability after feeding.\nThe parents report that the baby often arches his back during feeds and has trouble sleeping. Physical examination\nreveals a healthy-appearing infant with no signs of dehydration. Which of the following is the most appropriate next step\nin management?","options":{"A":"A. Start proton pump inhibitor therapy.","B":"B. Recommend thickened feeds.","C":"C. Refer to a pediatric gastroenterologist.","D":"OD. Advise the parents to hold the baby upright after feeds.","E":"E. Perform an upper gastrointestinal series."},"source_answer":"D","source_explanation":"The infant described in the scenario is exhibiting typical signs of gastro-oesop