INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('64f5c57b852fd458e4ae','Pediatric amedex 2025.pdf','113','Paediatrics','Concerned parents of a 7-year-old boy have brought him to your clinic after he passed a large bloody stool
this morning. No pain or discomfort is reported. Which one of the following can be the most likely cause?','{"A":"A. Meckel’s diverticulum.","B":"B. Duodenal ulcer.","C":"OC. Colon polyp.","D":"D. Diverticulitis of the colon.","E":"E. Intussusception."}','C','A large bloody stool, especially if painless, in a 7-year-old child is very likely to be caused by a juvenile colonic
polyp.

Juvenile polyps are benign hamartomas, occurring between the ages 2 and 8 years, with a peak at 3 to 4
years. Patients usually present with painless rectal bleeding; however, a few children may have lower
abdominal pain from traction of the polyp. More than 60% of patients have a palpable polyp on rectal
examination.

(Option A) Meckel’s diverticulum can result in massive rectal bleeding, often associated with central
abdominal pain. However, the presentation is expected earlier in life and is also less common than juvenile

polyps.

(Option B) Duodenal ulcer is most likely to present with melena or hematemesis rather than large rectal
bleeding.

(Options D and E) Diverticular disease is not common among children of this age group, neither is
intussusception. Moreover, intussusception is often painful.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[113],"source_qid":null,"duplicate_group_id":"exact-ab16db3657af","duplicate_sources":[{"record_id":"64f5c57b852fd458e4ae","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":113,"source_qid":null},{"record_id":"6da21d1c3afd58fa635f","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":176,"source_qid":null},{"record_id":"dd792d982f4c74f69702","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":177,"source_qid":null},{"record_id":"cbfc50b15e15102b6028","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1317,"source_qid":"905"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"64f5c57b852fd458e4ae","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":113,"supporting_pages":[113],"source_qid":null,"domain_hint":"Paediatrics","stem":"Concerned parents of a 7-year-old boy have brought him to your clinic after he passed a large bloody stool\nthis morning. No pain or discomfort is reported. Which one of the following can be the most likely cause?","options":{"A":"A. Meckel’s diverticulum.","B":"B. Duodenal ulcer.","C":"OC. Colon polyp.","D":"D. Diverticulitis of the colon.","E":"E. Intussusception."},"source_answer":"C","source_explanation":"A large bloody stool, especially if painless, in a 7-year-old child is very likely to be caused by a juvenile colonic\npolyp.\n\nJuvenile polyps are benign hamartomas, occurring between the ages 2 and 8 years, with a peak at 3 to 4\nyears. Patients usually present with painless rectal bleeding; however, a few children may have lower\nabdominal pain from traction of the polyp. More than 60% of patients have a palpable polyp on rectal\nexamination.\n\n(Option A) Meckel’s diverticulum can result in massive rectal bleeding, often associated with central\nabdominal pain. However, the presentation is expected earlier in life and is also less common than juvenile\n\npolyps.\n\n(Option B) Duodenal ulcer is most likely to present with melena or hematemesis rather than large rectal\nbleeding.\n\n(Options D and E) Diverticular disease is not common among children of this age group, neither is\nintussusception. Moreover, intussusception is often painful.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ab16db3657af9363a2dfbf5fcbc5495ef743ed47","duplicate_group_id":"exact-ab16db3657af","duplicate_sources":[{"record_id":"64f5c57b852fd458e4ae","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":113,"source_qid":null},{"record_id":"6da21d1c3afd58fa635f","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":176,"source_qid":null},{"record_id":"d