INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('64f5c57b852fd458e4ae','src-v294-5083b15f',NULL,'113','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','Concerned parents of a 7-year-old boy have brought him to your clinic after he passed a large bloody stool
this morning. No pain or discomfort is reported. Which one of the following can be the most likely cause?',NULL,'C','A large bloody stool, especially if painless, in a 7-year-old child is very likely to be caused by a juvenile colonic
polyp.

Juvenile polyps are benign hamartomas, occurring between the ages 2 and 8 years, with a peak at 3 to 4
years. Patients usually present with painless rectal bleeding; however, a few children may have lower
abdominal pain from traction of the polyp. More than 60% of patients have a palpable polyp on rectal
examination.

(Option A) Meckel’s diverticulum can result in massive rectal bleeding, often associated with central
abdominal pain. However, the presentation is expected earlier in life and is also less common than juvenile

polyps.

(Option B) Duodenal ulcer is most likely to present with melena or hematemesis rather than large rectal
bleeding.

(Options D and E) Diverticular disease is not common among children of this age group, neither is
intussusception. Moreover, intussusception is often painful.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[113],"source_qid":null,"duplicate_group_id":"exact-ab16db3657af","duplicate_sources":[{"record_id":"64f5c57b852fd458e4ae","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":113,"source_qid":null},{"record_id":"6da21d1c3afd58fa635f","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":176,"source_qid":null},{"record_id":"dd792d982f4c74f69702","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":177,"source_qid":null},{"record_id":"cbfc50b15e15102b6028","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1317,"source_qid":"905"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_