INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d58e67d00f07e5a62f73','Pediatric amedex 2025.pdf','114','Paediatrics','An unvaccinated 3-year-old child has had severe paroxysms of cough with inspiratory whoop for the past 4 weeks.
Bouts of cough have been followed by vomiting. Cough bouts occur more at night. Physical examination is normal.
Laboratory investigations is significant for lymphocytosis. Which of the following is not true regarding this condition?','{"A":"A. Antibiotics at this stage are not likely to reduce the communicability of the disease.","B":"B. Antibiotics often do not improve the symptoms of the patient.","C":"C. School exclusion for him is not necessary anymore.","D":"D. Given the time of presentation, antibiotic prophylaxis for the close contacts is not likely to be effective.","E":"OE. Antibiotic prophylaxis for his household is required at this stage."}','E','This child has signs and symptoms of whooping cough or pertussis. Pertussis is a respiratory infection caused by
Bordetella pertussis. The clinical illness is divided into three stages- catarrhal, paroxysmal, and convalescent:

Catarrhal phase - Mild cough and coryza often lasting 1 to 2 weeks. Fever is uncommon, and if present, is usually low
grade. Instead of improving, the cough gradually increases, unlike a typical upper respiratory infection.

Paroxysmal phase - In the paroxysmal phase, coughing persists and severity increases, occurring in paroxysmal
attacks. The classic cough of pertussis is distinctive. The paroxysm is a long series of coughs, during which the child
may develop gagging and cyanosis and appear to be struggling for breath. Whooping, which is characterized by the
noise of the forced inspiratory effort, may be observed following a coughing attack during the paroxysmal phase. Post-
tussive vomiting occurs frequently.

Convalescent phase - In convalescent phase, the cough begins to subside, and the child enters the convalescent
stage. The cough continues to decrease gradually over several weeks to months.

Antibiotics are usually given to reduce the spread of the disease to others; however there is little evidence about
improvement of the patient''s symptoms with antibiotics, unless it is given in the catarrhal phase (less than 14 days of
symptoms) which is not the case most of the time. This child has had the symptoms for 4 weeks and is over the
infectious period. Therefore, antibiotics at this stage are not likely to reduce the communicability of the disease (option
A); neither do they decrease the symptoms (option B).

Unimmunized (<3 doses) household and close children contacts less than 7 years of age must be excluded from
school or child care for 14 days from the last exposure to infection OR until they have taken 5 days of effective
antibiotics. The index case should be excluded from school while in the infectious period or until he receives 5 days of
antibiotics. This child is beyond the infectivity period is school exclusion for him is not necessary anymore (option C).

Chemoprophylaxis to prevent secondary transmission is not recommended in most situations because of the delayed
presentation of the index case and the cost and adverse effects of antibiotics. However, given the high risk of mortality
and morbidity associated with infection of newborns, particularly in the context of the rising incidence of pertussis in the
community and the high transmission rate, chemoprophylaxis is recommended to limit transmission to those most at
risk of the infection (young infants). Data to support this recommendation are limited.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[114],"source_qid":null,"duplicate_group_id":"exact-fa09fb22d81f","duplicate_sources":[{"record_id":"d58e67d00f07e5a62f73","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":114,"source_qid":null},{"record_id":"73bb841cd8b9c710e759","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":83,"source_qid":null},{"record_id":"8a88b8d95ed2e5def0fa","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1297,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"d58e67d00f07e5a62f73","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":114,"supporting_pages":[114],"source_qid":null,"domain_hint":"Paediatrics","stem":"An unvaccinated 3-year-old child has had severe paroxysms of cough with inspiratory whoop for the past 4 weeks.\nBouts of cough have been followed by vomiting. Cough bouts occur more at night. Physical examination is normal.\nLaboratory investigations is significant for lymphocytosis. Which of the following is not true regarding this condition?","options":{"A":"A. Antibiotics at this stage are not likely to reduce the communicability of the disease.","B":"B. Antibiotics often do not improve the symptoms of the patient.","C":"C. School exclusion for him is not necessary anymore.","D":"D. Given the time of presentation, antibiotic prophylaxis for the close contacts is not likely to be effective.","E":"OE. Antibiotic prophylaxis for his household is required at this stage."},"source_answer":"E","source_explanation":"This child has signs and symptoms of whooping cough or pertussis. Pertussis is a respiratory infection caused by\nBordetella pertussis. The clinical illness is divided into three stages- catarrhal, paroxysmal, and convalescent:\n\nCatarrhal phase - Mild cough and coryza often lasting 1 to 2 weeks. Fever is uncommon, and if present, is usually low\ngrade. Instead of improving, the cough gradually increases, unlike a typical upper respiratory infection.\n\nParoxysmal phase - In the paroxysmal phase, coughing persists and severity increases, occurring in paroxysmal\nattacks. The classic cough of pertussis is distinctive. The paroxysm is a long series of coughs, during which the child\nmay develop gagging and cyanosis and appear to be struggling for breath. Whooping, which is characterized by the\nnoise of the forced inspiratory effort, may be observed following a coughing attack during the paroxysmal phase. Post-\ntussive vomiting occurs frequently.\n\nConvalescent phase - In convalescent phase, the cough begins to subside, and the child enters the convalescent\nstage. The cough continues to decrease gradually over several weeks to months.\n\nAntibiotics are usually given to reduce the spread of the disease to others; however there is little evidence about\nimprovement of the patient''s symptoms with antibiotics, unless it is given in the catarrhal phase (less than 14 days of\nsymptoms) which is not the case most of the time. This child has had the symptoms for 4 weeks and is over the\ninfectious period. Therefore, antibiotics at this stage are not likely to reduce the communicability of the disease (option\nA); neither do they decrease the symptoms (option B).\n\nUnimmunized (<3 doses) household and close children contacts less than 7 years of age must be excluded from\nschool or child care for 14 days from the last exposure to infection OR until they have taken 5 days of effective\nantibiotics. The index case should be excluded from school while in the infectious period or until he receives 5 days of\nantibiotics. This child is beyond the infectivity period is school exclusion for him is not necessary anymore (option C).\n\nChemoprophylaxis to prevent secondary transmission is not recommended in most situations because of the delayed\npresentation of the index case and the cost and adverse effects of antibiotics. However, given the high risk of mortality\nand morbidity associated with infection of newborns, particularly in the context of the rising incidence of pertussis in the\ncommunity and the high transmission rate, chemoprophylaxis is recommended to limit transmission to those most at\nrisk of the infection (young infants). Data to support this recommendation are limited.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","dose","immuniz","prophyl","vaccin"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"fa09fb22d81f960d1a3d7308f00da6e92a15290b","duplicate_group_id":"exact-fa09fb22d81f","duplicate_sources":[{"record_id":"d58e67d00f07e5a62f73","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":114,"source_qid":null},{"record_id":"73bb841cd8b9c710e759","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":83,"source_qid":null},{"record_id":"8a88b8d95ed2e5def0fa","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1297,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
