INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5ea1676537ff33e8c15d','Pediatric amedex 2025.pdf','116','Paediatrics','A 4-year-old boy is brought to you with a painful left knee and limping. Recently, the child had a diagnosis of ‘irritable
hip''. On examination, internal rotation and abduction of the left hip joint is limited. An X-ray of the hip shows increased
joint space. Which one of the following is the next best step in management?','{"A":"A. Encourage activity.","B":"B. Use crutches and encourage bed rest.","C":"C. Do a follow up X-ray next week.","D":"D. Hip joint aspiration under general anesthesia.","E":"OE. Referral to an orthopedic surgeon."}','E','The clinical and radiological findings are highly suggestive of Legg - Calve - Perthes disease as the most likely
diagnosis.

Legg-Calve-Perthes disease is caused by idiopathic avascular necrosis of the femoral epiphysis, possibly due to
repeated multiple vascular occlusive episodes that involve the femoral head. It typically presents with hip/knee pain
and/or limp of acute or insidious onset, most commonly in Caucasian boys between the ages of 4 and 10 years, with
peak incidence at 5 to 7 years of age. In 15% of the patients the condition is bilateral.

In children older than 8 years, the condition is associated with higher incidence of osteoarthritis in adulthood. Younger
children (less than 6 years old) have a greater capacity for the acetabulum to undergo remodeling to accommodate
irregularities in the shape of the femoral head.

As there is a significant risk of femoral head destruction due to avascular necrosis, immediate referral to orthopedic
specialist is essential and the most appropriate next step in management.

(Option A) Encouraging activity is not an appropriate option because reducing the weight on the hip joint is an
essential part of treatment.

(Option B) Activities should be restricted and the patient should be offered to use crutches at least until the time he is
reviewed by an orthopedic surgeon. Although, use of crutches and encouraging bed rest are partially effective, they
are not the definite management for such patients and are only temporary measures to prevent worsening of the
problem.

(Option C) Legg-Calve-Perthes requires urgent referral and delayed referral with further investigations is not
appropriate. The condition will not improve spontaneously and follow-up X-rays unnecessarily delays appropriate
treatment.

(Option D) Aspiration under general anesthesia is performed to exclude septic arthritis if history suggest such
diagnosis. This child is afebrile and his problem has had an insidious development, making septic arthritis less likely.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[116],"source_qid":null,"duplicate_group_id":"exact-3b8bd8a89b2f","duplicate_sources":[{"record_id":"5ea1676537ff33e8c15d","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":116,"source_qid":null},{"record_id":"397fc74c4564899f25f2","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":127,"source_qid":null},{"record_id":"84cecb8cfa1f74047a3f","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":128,"source_qid":null},{"record_id":"46921f207864ef46cc72","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1276,"source_qid":"520"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"5ea1676537ff33e8c15d","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":116,"supporting_pages":[116],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 4-year-old boy is brought to you with a painful left knee and limping. Recently, the child had a diagnosis of ‘irritable\nhip''. On examination, internal rotation and abduction of the left hip joint is limited. An X-ray of the hip shows increased\njoint space. Which one of the followi