INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7709dd4cbab09b7d0976','Pediatric amedex 2025.pdf','117','Paediatrics','A 3-year-old child is brought to your office by his mother with complaints of diarrhea and colicky abdominal pains for the past three days. Which one of the following
can be the most likely diagnosis?','{"A":"A. Giardiasis.","B":"OB. Norovirus gastroenteritis.","C":"C. Perforated appendicitis.","D":"D. Staphylococcal gastroenteritis.","E":"E. Shigellosis."}','B','Of the options, gastroenteritis caused by Norovirus is the most likely diagnosis.

Norovirus is a major human pathogen across the world. It is estimated to account for 95% of non-bacterial gastroenteritis in outbreaks in industrialized countries
such as Australia and 50% of all gastroenteritis outbreaks worldwide. All age groups are susceptible.

The most common route of transmission is via fecal-oral route. Consumption of contaminated food such as salads, ice, water, fresh fruit, bakery goods, and cold
meats is a major cause of infection. In a minority of cases transmission occurs via aerosol/personal contact or fomites from toys, carpet, handles, surfaces etc.

The incubation period after digestion is 24-48 hours but it can occur as early as 12 hours.
Clinical manifestation includes:
Common

¢ Nausea
¢ Vomiting
¢ Diarrhea
e¢ Abdominal cramps

Less common

¢ Headache

e Low-grade fever
* Chills

¢ Muscle aches
¢ Malaise

Diarrhea of Norovirus gastroenteritis is non-inflammatory and is not bloody or mucoid. Except in outbreaks, no diagnostic test is necessary. PCR of the stool is the
method of choice. Treatment is only symptomatic.

(Option A) Giardiasis should be thought of in hikers, campers, or those with history of drinking fresh water. Symptoms of acute giardiasis include:

¢ Diarrhea (sudden in onset; initially may be watery) - 90%
¢ Malaise - 85%

¢ Foul-smelling and fatty stools (steatorrhea) - 70%

¢ Abdominal cramps and bloating - 70%

e Flatulence - 75%

¢ Nausea - 70%

¢ Weight loss — 65%

¢ Vomiting — 30%

e Fever -10-15%

Symptoms usually develop after an incubation period of 7 to 14 days (range 1 to 45 days) and may last 2-4 weeks. Significant weight loss can occur in about 50% of
symptomatic patients.

With diarrhea and abdominal cramps, giardiasis can be a possibility; however, no history of using fresh water makes this diagnosis less likely.
(Option C) Perforated appendicitis presents with a completely different clinical picture including systemic toxicity and sign and symptoms of peritonitis.

(Option D) Staphylococcal gastroenteritis is a self-limiting condition caused by contaminated foods. Nausea and vomiting are more pronounced, and diarrhea is
less common.

(Option E) Shigellosis is an infection of the lower gastrointestinal tract. Patients with Shigella gastroenteritis typically present with high fever, abdominal cramps, and
bloody and mucoid diarrhea. The incubation period ranges from 1 to 7 days. The disease typically begins with constitutional symptoms such as fever, anorexia, and
malaise. Initially, diarrhea is watery, but subsequently may contain blood and mucus. Tenesmus is a common complaint.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[117],"source_qid":null,"duplicate_group_id":"exact-6af8b9ea2ad1","duplicate_sources":[{"record_id":"7709dd4cbab09b7d0976","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":117,"source_qid":null},{"record_id":"727e0749635d967f6bcb","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":166,"source_qid":null},{"record_id":"3498bdbac533e6fc71c7","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":165,"source_qid":null},{"record_id":"5e0076d5e6d96fffe633","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1367,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"7709dd4cbab09b7d0976","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":117,"supporting_pages":[117],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 3-year-old child is brought to your office by his mother with complaints of diarrhea and colicky abdominal pains for the past three days. Which one of the following\ncan be the most likely diagnosis?","options":{"A":"A. Giardiasis.","B":"OB. Norovirus gastroenteritis.","C":"C. Perforated appendicitis.","D":"D. Staphylococcal gastroenteritis.","E":"E. Shigellosis."},"source_answer":"B","source_explanation":"Of the options, gastroenteritis caused by Norovirus is the most likely diagnosis.\n\nNorovirus is a major human pathogen across the world. It is estimated to account for 95% of non-bacterial gastroenteritis in outbreaks in industrialized countries\nsuch as Australia and 50% of all gastroenteritis outbreaks worldwide. All age groups are susceptible.\n\nThe most common route of transmission is via fecal-oral route. Consumption of contaminated food such as salads, ice, water, fresh fruit, bakery goods, and cold\nmeats is a major cause of infection. In a minority of cases transmission occurs via aerosol/personal contact or fomites from toys, carpet, handles, surfaces etc.\n\nThe incubation period after digestion is 24-48 hours but it can occur as early as 12 hours.\nClinical manifestation includes:\nCommon\n\n¢ Nausea\n¢ Vomiting\n¢ Diarrhea\ne¢ Abdominal cramps\n\nLess common\n\n¢ Headache\n\ne Low-grade fever\n* Chills\n\n¢ Muscle aches\n¢ Malaise\n\nDiarrhea of Norovirus gastroenteritis is non-inflammatory and is not bloody or mucoid. Except in outbreaks, no diagnostic test is necessary. PCR of the stool is the\nmethod of choice. Treatment is only symptomatic.\n\n(Option A) Giardiasis should be thought of in hikers, campers, or those with history of drinking fresh water. Symptoms of acute giardiasis include:\n\n¢ Diarrhea (sudden in onset; initially may be watery) - 90%\n¢ Malaise - 85%\n\n¢ Foul-smelling and fatty stools (steatorrhea) - 70%\n\n¢ Abdominal cramps and bloating - 70%\n\ne Flatulence - 75%\n\n¢ Nausea - 70%\n\n¢ Weight loss — 65%\n\n¢ Vomiting — 30%\n\ne Fever -10-15%\n\nSymptoms usually develop after an incubation period of 7 to 14 days (range 1 to 45 days) and may last 2-4 weeks. Significant weight loss can occur in about 50% of\nsymptomatic patients.\n\nWith diarrhea and abdominal cramps, giardiasis can be a possibility; however, no history of using fresh water makes this diagnosis less likely.\n(Option C) Perforated appendicitis presents with a completely different clinical picture including systemic toxicity and sign and symptoms of peritonitis.\n\n(Option D) Staphylococcal gastroenteritis is a self-limiting condition caused by contaminated foods. Nausea and vomiting are more pronounced, and diarrhea is\nless common.\n\n(Option E) Shigellosis is an infection of the lower gastrointestinal tract. Patients with Shigella gastroenteritis typically present with high fever, abdominal cramps, and\nbloody and mucoid diarrhea. The incubation period ranges from 1 to 7 days. The disease typically begins with constitutional symptoms such as fever, anorexia, and\nmalaise. Initially, diarrhea is watery, but subsequently may contain blood and mucus. Tenesmus is a common complaint.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"6af8b9ea2ad1d674843722b97d673fcdb8512718","duplicate_group_id":"exact-6af8b9ea2ad1","duplicate_sources":[{"record_id":"7709dd4cbab09b7d0976","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":117,"source_qid":null},{"record_id":"727e0749635d967f6bcb","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":166,"source_qid":null},{"record_id":"3498bdbac533e6fc71c7","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":165,"source_qid":null},{"record_id":"5e0076d5e6d96fffe633","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1367,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
