INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('7709dd4cbab09b7d0976','src-v294-5083b15f',NULL,'117','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','A 3-year-old child is brought to your office by his mother with complaints of diarrhea and colicky abdominal pains for the past three days. Which one of the following
can be the most likely diagnosis?',NULL,'B','Of the options, gastroenteritis caused by Norovirus is the most likely diagnosis.

Norovirus is a major human pathogen across the world. It is estimated to account for 95% of non-bacterial gastroenteritis in outbreaks in industrialized countries
such as Australia and 50% of all gastroenteritis outbreaks worldwide. All age groups are susceptible.

The most common route of transmission is via fecal-oral route. Consumption of contaminated food such as salads, ice, water, fresh fruit, bakery goods, and cold
meats is a major cause of infection. In a minority of cases transmission occurs via aerosol/personal contact or fomites from toys, carpet, handles, surfaces etc.

The incubation period after digestion is 24-48 hours but it can occur as early as 12 hours.
Clinical manifestation includes:
Common

¢ Nausea
¢ Vomiting
¢ Diarrhea
e¢ Abdominal cramps

Less common

¢ Headache

e Low-grade fever
* Chills

¢ Muscle aches
¢ Malaise

Diarrhea of Norovirus gastroenteritis is non-inflammatory and is not bloody or mucoid. Except in outbreaks, no diagnostic test is necessary. PCR of the stool is the
method of choice. Treatment is only symptomatic.

(Option A) Giardiasis should be thought of in hikers, campers, or those with history of drinking fresh water. Symptoms of acute giardiasis include:

¢ Diarrhea (sudden in onset; initially may be watery) - 90%
¢ Malaise - 85%

¢ Foul-smelling and fatty stools (steatorrhea) - 70%

¢ Abdominal cramps and bloating - 70%

e Flatulence - 75%

¢ Nausea - 70%

¢ Weight loss — 65%

¢ Vomiting — 30%

e Fever -10-15%

Symptoms usually develop after an incubation period of 7 to 14 days (range 1 to 45 days) and may last 2-4 weeks. Significant weight loss can occur in about 50% of
symptomatic patients.

With diarrhea and abdominal cramps, giardiasis can be a possibility; however, no history of using fresh water makes this diagnosis less likely.
(Option C) Perforated appendicitis presents with a completely different clinical picture including systemic toxicity and sign and symptoms of peritonitis.

(Option D) Staphylococcal gastroenteritis is a self-limiting condition caused by contaminated foods. Nausea and vomiting are more pronounced, and diarrhea is
less common.

(Option E) Shigellosis is an infection of the lower gastrointestinal tract. Patients with Shigella gastroenteritis typically present with high fever, abdominal cramps, and
bloody and mucoid diarrhea. The incubation period ranges from 1 to 7 days. The disease typically begins with constitutional symptoms such as fever, anorexia, and
malaise. Initially, diarrhea is watery, but subsequently may contain blood and mucus. Tenesmus is a common complaint.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[117],"source_qid":null,"duplicate_group_id":"exact-6af8b9ea2ad1","duplicate_sources":[{"record_id":"7709dd4cbab09b7d0976","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":117,"source_qid":null},{"record_id":"727e0749635d967f6bcb","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":166,"source_qid":null},{"record_id":"3498bdbac533e6fc71c7","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":165,"source_qid":null},{"record_id":"5e0076d5e6d96fffe633","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1367,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_y