INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('37819a1b82b22a5164be','Pediatric amedex 2025.pdf','119','Paediatrics','Parents of an 11-year-old boy have brought him to your clinic for assessment because they believe he is obese. On
examination, his weight and height are on 90 and 50 percentiles for sex- and age-matched growth charts respectively.
Which one of the following is the most appropriate investigation to consider for him?',NULL,'C','For children and adolescents aged 2—18 years, growth is monitored based on age, height, and weight, using sex-
specific Body Mass Index (BMI) percentile charts. BMI is not a fixed measure in this age group but varies with normal
growth, stage of puberty, and sex. Either the United States Centers for Disease Prevention and Control (US-CDC) or
WHO BMI percentile charts may be used, with the same chart used over time to allow for consistent monitoring of

growth. The US-CDC categorizes overweight as between the 85''" and 95" percentile and obesity as above the g5th
percentile. The WHO categorizes overweight as between the 85" and 97" BMI percentiles and obesity as above the

g7th percentile. These categories are not diagnostic but contribute to the overall clinical impression of the child or
adolescent being measured.

This boy, based on either chart, is overweight (>85!"), The likelihood that childhood overweight and obesity will persist
into adulthood increases with the age of the child and with the presence of parental obesity. One of the strongest
predictors of a child’s weight is the weight status of his/her parents. For overweight or obese children, initial assessment
by history and clinical assessment should determine current health problems and risks for future disease.

History taking includes developmental history, physical and mental health (including family history of obesity), and
current health behaviors.

Clinical assessment includes pubertal stage, possible causes for overweightness or obesity (e.g., hypothyroidism), and
indicators of comorbidities (e.g., raised blood pressure, joint pain, gastrointestinal symptoms, insulin resistance,
intertrigo, dental health etc.)

It is also very important that secondary causes for obesity are considered and excluded. Of the options, TSH is an
appropriate investigation for exclusion of hypothyroidism as a potential cause of overweightness.

(Options A and B) There is no clinical finding to suggest FSH/LH or GH as an initial assessment. Such clinical findings
may include but not limited to short stature (necessitating GH evaluation) and delayed puberty (for TSH, FSH and LH).

(Option D) Bone age is often used as the initial assessment for short stature that is not the problem here.

(Option E) This boy is overweight and reassurance cannot be given because there might be an underlying cause
present and also the child is at increased risk of obesity-relates health problems in the future.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[119],"source_qid":null,"duplicate_group_id":"exact-6d2e9566f611","duplicate_sources":[{"record_id":"37819a1b82b22a5164be","record_type":"visual_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":119,"source_qid":null},{"record_id":"a32a2c65f5fdc5227a15","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":4,"source_qid":null},{"record_id":"2f8cb1bad496f9bc768d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1364,"source_qid":null}],"parser_version":"2.9.2-manual-context-utility-complete-2026-09-23","parser_mode":"v29_contextual_visual_preserve","text_method":"v28_existing_ocr+page_image","visual_asset":"visual_assets/Pediatric_amedex_2025__fe3883efd6a6/page_00119.jpg","asset_preview_url":"https://drive.google.com/file/d/1Xub6X7dUjmkOfn7FOfRyohLJ_7X5zCXv/preview"}','visual_assets/Pediatric_amedex_2025__fe3883efd6a6/page_00119.jpg','https://drive.google.com/thumbnail?id=1Xub6X7dUjmkOfn7FOfRyohLJ_7X5zCXv&sz=w1600','source_page_image',NULL,'needs_verification','[]','medium','{"record_id":"37819a1b82b22a5164be","record_type":"visual_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":119,"supporting_pages":[119],"source_qid":null,"domain_hint":"Paediatrics","stem":"Parents of an 11-year-old boy have brought him to your clinic for assessment because they believe he is obese. On\nexamination, his weight and height are on 90 and 50 percentiles for sex- and age-matched growth ch