INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('a307e3c029453e002267','src-v294-5083b15f',NULL,'120','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','A 7-month-old child is brought to your practice with paroxysmal cough and vomiting for 2 weeks and relative wellness and health
in between paroxysms. You suspect he may have whooping cough (pertussis). He has already been started on azithromycin. He
lives at home with his mother, father and older brothers, aged 3 and 5 years. Neither of his brothers have been immunized
against pertussis. Which one of the following options is the most appropriate next action to take?',NULL,'C','This child is older than 6 months and does not have any serious complication of Bordetella pertussis infections such as cyanosis,
apnea or pneumonia; therefore, admission to hospital is not required.

The decision as to whether a child is immunized is made by the parents. Parents can decide to not immunize their children and it
is not an act subject to notification to child protection authorities.

Parents can be talked into vaccinating their children for their benefit but they cannot be forced to because this is their right to
refuse vaccination of their children. Moreover, vaccination at this point will not help the current situation.

Prophylaxis against pertussis in an attempt to decrease spread to the community Is indicated in the following situations:

e The close contact with confirmed case of pertussis (index case) while index case is infectious, which is within the first 21
days of cough and <5 days of antibiotics

AND

e First contact was within 14 days (or within 21 days for infants <6 months) — beyond that time prophylaxis is not effective
lf the above criteria are met, the following groups should receive prophylactic antibiotics:
Children

e Age <6 months; OR

e <3 doses pertussis vaccine; OR

e There is a household member aged <6 months; OR

¢ Children who attend childcare in same room as infant <6 months

Adults (regardless of immunization status)

e Expectant parents in last month of pregnancy; OR

e Healthcare workers in maternity hospital or newborn nursery; OR
¢ Childcare worker in close contact with infants <6 months; OR

e Household members aged <6 months

Prophylaxis is indicated for the 3- and 5-year-old children, but not for parents. Therefore, the option suggesting that all family
members should receive prophylactic antibiotics is incorrect. It is recommended that close contacts that are not up-to-date with
their pertussis immunization should be given DTPa or dTpa as soon after exposure as possible. In the absence of an option
suggesting prophylaxis for 3- and 5-year-old children, immediate vaccination of these two children would be the most appropriate
alternative option. Vaccinated adults, who have not had pertussis-containing vaccine in the last 10 years, should receive a booster
dose by dIpa.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[120],"source_qid":null,"duplicate_group_id":"exact-62f88362a9db","duplicate_sources":[{"record_id":"a307e3c029453e002267","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":120,"source_qid":null},{"record_id":"ac803f67b1830e87f1c7","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":192,"source_qid":null},{"record_id":"1cf78d8930db6ae171e0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1305,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.curre