INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('395709382bd24262e919','Pediatric amedex 2025.pdf','122','Paediatrics','A 35-year-old woman gives birth to her second male baby through an uneventful vaginal delivery. The baby is preterm at 34 weeks
and weighs 3100 gr. Apgar''s scores in the first and 5''" minutes are 6 and 9, respectively. Almost one hour after birth, he develops
tachypnea and grunting, as well as intercostal recession. He is placed under the oxygen hood. In the next 4 hours, his condition
remarkably improves. Which one of the following could be the most likely diagnosis?','{"A":"A. Meconium aspiration.","B":"B. Birth asphyxia.","C":"OC. Transient tachypnea of the newborn.","D":"D. Respiratory distress syndrome.","E":"E. Tension pneumothorax."}','C','The scenario represents early-onset respiratory distress in a newborn with a near normal and normal APGAR score of 6 and 9 at 1
and 5 minutes. These scores exclude birth asphyxia (option B), which is defined as failure to establish breathing at birth. This
baby started breathing right after birth but developed respiratory problems shortly after.

Of the other options, transient tachypnea of the newborn (TTN) and respiratory distress syndrome (RDS) (option D) seem more
likely compared to others.

Transient tachypnea of the newborn (TTN) is a benign, self-limiting condition that can present in infants of any gestational age
shortly after birth. The pathophysiology is a delay in the clearance of fetal lung fluid after birth, which leads to ineffective gas
exchange, respiratory distress, and tachypnea. RDS on the other hand is caused by surfactant deficiency in preterm newborns.

Both TTN and RDS present with the following:

¢ Onset within the first few minutes to hours after birth.
e Physical exam findings usually include signs of respiratory distress:

© Tachypnea (respiratory rate greater than 60 per minute)
© Nasal flaring

© Grunting

Intercostal/subcostal/suprasternal retractions

oO

The distinctive feature between these two Is the clinical course. While TTN improves with supportive treatment usually within 6
hours of onset, RDS worsens over 48-72 hours before it improves. The fact that this newborn has made a remarkable recovery in
4 hours makes TTN a more likely diagnosis compared to RDS.

Meconium aspiration syndrome (option A) is a common cause of early-onset neonatal respiratory distress in near-term, term or
post-term neonates. One important clue to such diagnosis is the presence of meconium on the neonate’s body (meconium-stained
baby) or in the amniotic fluid. Prematurity and absence of any clues on the presence of meconium in the scenario are less likely.

Tension pneumothorax (option D) presents with acute onset respiratory distress. Diagnostic clues include tachycardia,
tachypnea, hypotension, asymmetrical respiratory movements, absence of breath sounds, and hyper-resonance of the affected
side and engorged neck and forehead veins. As none Is mentioned in the scenario, it is less likely to be the diagnosis.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[122],"source_qid":null,"duplicate_group_id":"exact-49e350e04e44","duplicate_sources":[{"record_id":"395709382bd24262e919","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":122,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"395709382bd24262e919","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":122,"supporting_pages":[122],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 35-year-old woman gives birth to her second male baby through an uneventful vaginal delivery. The baby is preterm at 34 weeks\nand weighs 3100 gr. Apgar''s scores in the first and 5''\" minutes are 6 and 9, respectively. Almost one hour after birth, he develops\ntachypnea and grunting, as well as intercostal recession. He is placed under the oxygen hood. In the next 4 hours, his condition\nremarkably improves. Which one of the following could be the most likely diagnosis?","options":{"A":"A. Meconium aspiration.","B":"B. Birth asphyxia.","C":"OC. Transient tachypnea of the newborn.","D":"D. Respiratory distress syndrome.","E":"E. Tension pneumothorax."},"source_answer":"C","source_explanation":"The scenario represents early-onset respiratory distress in a newborn with a near normal and normal APGAR score of 6 and 9 at 1\nand 5 minutes. These scores exclude birth asphyxia (option B), which is defined as failure to