INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4c99e8bc00f6439b4d37','Pediatric amedex 2025.pdf','123','Paediatrics','A 6-month-old infant presents with persistent eczema, vomiting, and diarrhea after starting formula feeding with cow''s milk-based
formula. Which of the following is the most appropriate initial management for this condition?','{"A":"A. Introduce solid foods to the diet.","B":"B. Switch to a soy-based formula.","C":"OC. Use an extensively hydrolysed formula.","D":"D. Administer oral antihistamines.","E":"E. Recommend a cow''s milk-containing diet."}',NULL,'Correct Answer Is

The clinical picture and the fact that the condition started after the introduction of Cows'' milk-based formula makes cow''s milk
protein allergy (CMPA) the most likely diagnosis. CMPA can be either an immune-mediated or non-immune-mediated reaction to
proteins found in cow''s milk. It can present with symptoms such as eczema, vomiting, diarrhea, and, in some cases, more severe
reactions like anaphylaxis. The symptoms typically appear in infants after introducing cow''s milk-based formula or dairy products.

For an infant suspected of having Cow''s Milk Protein Allergy (CMPA), the initial management involves removing cow''s milk proteins
from the diet. An extensively hydrolyzed formula is typically recommended as the first-line alternative. This type of formula has
proteins that are broken down into smaller peptides, which are less likely to cause an allergic reaction in infants with CMPA.

Cow''s milk protein allergy (CMPA) can be IgE- or non-IgE-mediated:
IgE-mediated CMPA

¢ This type involves an immediate allergic reaction, in which the immune system produces IgE antibodies in response to cow''s
milk proteins.

¢ Symptoms typically occur within minutes to hours after ingestion and can include hives, lip swelling, vomiting, wheezing, and
anaphylaxis in severe cases.

¢ This is the classic allergic reaction associated with food allergies.

Non-IgE-mediated CMPA

e In this type, the immune system does not produce IgE antibodies but involves other immune mechanisms (like T-cell-mediated
responses).

¢ Symptoms usually appear later (hours to days) after exposure to cow''s milk and can include eczema, diarrhea, vomiting, and
gastrointestinal issues such as abdominal pain.

¢ This form tends to be less immediately severe than IgE-mediated reactions but can still cause significant discomfort.

(Option A) Introducing solids may be appropriate at this age but would not address the suspected CMPA, and cow''s milk proteins
might still be present in solid foods.

(Option B) Switching to a soy-based formula is generally not recommended as the first option for infants with CMPA, as there is a
significant risk of cross-reactivity (about 10-14% of infants with CMPA may also react to soy).

(Option D) Antihistamines may help with allergic reactions but do not address the dietary cause and are not a primary treatment for
CMPA.

(Option E) Acow''s milk-containing diet would worsen symptoms and is not advised in the case of suspected CMPA.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[123],"source_qid":null,"duplicate_group_id":"exact-98465e534f1d","duplicate_sources":[{"record_id":"4c99e8bc00f6439b4d37","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":123,"source_qid":null},{"record_id":"679db94c769829f4c87d","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":33,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"4c99e8bc00f6439b4d37","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":123,"supporting_pages":[123],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 6-month-old infant presents with persistent eczema, vomiting, and diarrhea after starting formula feeding with cow''s milk-based\nformula. Which of the following is the most appropriate initial management for this condition?","options":{"A":"A. Introduce solid foods to the diet.","B":"B. Switch to a soy-based formula.","C":"OC. Use an extensively hydrolysed formula.","D":"D. Administer oral antihistamines.","E":"E. Recommend a cow''s milk-containing diet."},"source_answer":null,"source_explanation":"Correct Answer Is\n\nThe clinical picture and the fact that the condition started after the introduction of Cows'' milk-based formula makes cow''s milk\nprotein allergy (CMPA) the most likely diagnosis. CMPA can be either an immune-mediated or non-immune-mediated reaction to\nproteins found in cow''s milk. It can present with symptoms such as eczema, vomiting, diarrhea, and, in some cases, more severe\nreactions like anaphylaxis. The symptoms typically appear in infants after introducing cow''s milk-based formula or dairy products.\n\nFor an infant suspected of having Cow''s Milk Protein Allergy (CMPA), the initial management involves removing cow''s milk proteins\nfrom the diet. An extensively hydrolyzed formula is typically recommended as the first-line alternative. This type of formula has\nproteins that are broken down into smaller peptides, which are less likely to cause an allergic reaction in infants with CMPA.\n\nCow''s milk protein allergy (CMPA) can be IgE- or non-IgE-mediated:\nIgE-mediated CMPA\n\n¢ This type involves an immediate allergic reaction, in which the immune system produces IgE antibodies in response to cow''s\nmilk proteins.\n\n¢ Symptoms typically occur within minutes to hours after ingestion and can include hives, lip swelling, vomiting, wheezing, and\nanaphylaxis in severe cases.\n\n¢ This is the classic allergic reaction associated with food allergies.\n\nNon-IgE-mediated CMPA\n\ne In this type, the immune system does not produce IgE antibodies but involves other immune mechanisms (like T-cell-mediated\nresponses).\n\n¢ Symptoms usually appear later (hours to days) after exposure to cow''s milk and can include eczema, diarrhea, vomiting, and\ngastrointestinal issues such as abdominal pain.\n\n¢ This form tends to be less immediately severe than IgE-mediated reactions but can still cause significant discomfort.\n\n(Option A) Introducing solids may be appropriate at this age but would not address the suspected CMPA, and cow''s milk proteins\nmight still be present in solid foods.\n\n(Option B) Switching to a soy-based formula is generally not recommended as the first option for infants with CMPA, as there is a\nsignificant risk of cross-reactivity (about 10-14% of infants with CMPA may also react to soy).\n\n(Option D) Antihistamines may help with allergic reactions but do not address the dietary cause and are not a primary treatment for\nCMPA.\n\n(Option E) Acow''s milk-containing diet would worsen symptoms and is not advised in the case of suspected CMPA.","source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"98465e534f1d92ac3b6e0a281998b56fa6b98424","duplicate_group_id":"exact-98465e534f1d","duplicate_sources":[{"record_id":"4c99e8bc00f6439b4d37","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":123,"source_qid":null},{"record_id":"679db94c769829f4c87d","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":33,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active