INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9b40e207fb32f27aae2f','Pediatric amedex 2025.pdf','125','Paediatrics','A one-year-old female child is presented to you for a health checkup. She has normal growth parameters. She can sit unsupported, stand with assistance, and say ‘mama’. On
examination, a 2/6 systolic murmur is heard over the apex. The rest of the exam is completely normal. Which one of the following would be the most appropriate next step?','{"A":"A. Order ECG and chest X-ray.","B":"OB. Refer her to pediatric cardiologist.","C":"C. Reassure the parents as this is an innocent murmur.","D":"D. Refer her for emergency echocardiography.","E":"E. Tell the parents that she can have a congenital heart disease."}','B','Heart murmurs are common in healthy infants, children, and adolescents. Despite the fact that most heart murmurs are not pathologic, a murmur may be the only manifestation of a serious
underlying heart disease.

With either of the following present, the murmur should be considered pathological unless proven otherwise:

¢ Family history of sudden cardiac death or congenital heart disease
¢ In utero exposure to certain medications or alcohol

* Maternal diabetes mellitus

¢ History of rheumatic fever

¢ History of Kawasaki disease

When a murmur is present on heart auscultation, a thorough physical exam, including the following, should be performed:

¢ Vital signs

¢ Peripheral pulses and perfusion

¢ Exercise tolerance (age-matched)

¢ Auscultation over the heart valves

¢ Looking for respiratory or gastrointestinal manifestations of cardiac diseases

An innocent murmur is a physiologic murmur with the following characteristics (7 ‘S’s):

1. Sensitive — changes with child’s position or with respiration

2. Short duration (not holosystolic)

3. Single — no associated clicks or gallops

4. Small — murmur limited to a small area and non-radiating

5. Soft — low amplitude (up to 2/6 or very rarely to 3/6)

6. Sweet -— no harsh sounding (some innocent murmurs my sound harsher than the others, but generally physiologic murmurs are not harsh in nature), no thrills
7. Systolic — occurs during and is limited to systole

With the presence of either of the following, the murmur is pathologic:

¢ Grade 3/6 or higher murmurs

¢ Harsh quality

¢ Abnormal S2

¢ The presence of a systolic click

¢ Increased intensity with decreased venous return (e.g., when the patient stands)

¢ The patient has any symptoms that could be related to a cardiac condition (e.g. shortness of breath, chest pain, poor feeding, etc.)

In the following situations, the patient should be referred to a pediatric cardiologist:

¢ Murmurs in infancy, especially in the first 6 months

¢ There is a family history of sudden cardiac death or congenital heart disease

¢ There are cardiac symptoms — shortness of breath, poor feeding, failure to thrive, chest pain, fatigability, etc.
¢ There are chromosomal abnormalities

¢ The diagnosis is equivocal

This child is completely healthy and has no associated physical finding suggestive of a cardiac pathology. The murmur itself, on the other hand, has all characteristic features of an
innocent physiologic murmur, but since she is in the infancy period, referral to a specialist (preferably a pediatric cardiologist) is the most appropriate option to consider.

(Option A) Chest X-ray and electrocardiography are of little value in assessment of the underlying cause of a murmur in a child. Chest X-rays were obtained previously as a part of
assessment, but not an acceptable practice today.

(Option C) Although this murmur is likely to be innocent, parents cannot be reassured unless full evaluation by a pediatric cardiologist excludes any pathologic etiology.
(Option D) Echocardiography is the investigation of choice that may be considered by the pediatric cardiologist for further assessment.

(Option E) Although parents should be informed of all possibilities, telling them that their baby has heart disease while the murmur is more likely to be innocent and no further assessment
has been carried out is not appropriate.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[125],"source_qid":null,"duplicate_group_id":"exact-d84fba4f1f42","duplicate_sources":[{"record_id":"9b40e207fb32f27aae2f","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":125,"source_qid":null},{"record_id":"9dbc042c981c43d80c11","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":105,"source_qid":null},{"record_id":"280f9f65fabbab50a70f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1266,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"9b40e207fb32f27aae2f","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":125,"supporting_pages":[125],"source_qid":null,"domain_hint":"Paediatrics","stem":"A one-year-old female child is presented to you for a health checkup. She has normal growth parameters. She can sit unsupported, stand with assistance, and say ‘mama’. On\nexamination, a 2/6 systolic murmur is heard over the apex. The rest of the exam is completely normal. Which one of the following would be the most appropriate next step?","options":{"A":"A. Order ECG and chest X-ray.","B":"OB. Refer her to pediatric cardiologist.","C":"C. Reassure the parents as this is an innocent murmur.","D":"D. Refer her for emergency echocardiography.","E":"E. Tell the parents that she can have a congenital heart disease."},"source_answer":"B","source_explanation":"Heart murmurs are common in healthy infants, children, and adolescents. Despite the fact that most heart murmurs are not pathologic, a murmur may be the only manifestation of a serious\nunderlying heart disease.\n\nWith either of the following present, the murmur should be considered pathological unless proven otherwise:\n\n¢ Family history of sudden cardiac death or congenital heart disease\n¢ In utero exposure to certain medications or alcohol\n\n* Maternal diabetes mellitus\n\n¢ History of rheumatic fever\n\n¢ History of Kawasaki disease\n\nWhen a murmur is present on heart auscultation, a thorough physical exam, including the following, should be performed:\n\n¢ Vital signs\n\n¢ Peripheral pulses and perfusion\n\n¢ Exercise tolerance (age-matched)\n\n¢ Auscultation over the heart valves\n\n¢ Looking for respiratory or gastrointestinal manifestations of cardiac diseases\n\nAn innocent murmur is a physiologic murmur with the following characteristics (7 ‘S’s):\n\n1. Sensitive — changes with child’s position or with respiration\n\n2. Short duration (not holosystolic)\n\n3. Single — no associated clicks or gallops\n\n4. Small — murmur limited to a small area and non-radiating\n\n5. Soft — low amplitude (up to 2/6 or very rarely to 3/6)\n\n6. Sweet -— no harsh sounding (some innocent murmurs my sound harsher than the others, but generally physiologic murmurs are not harsh in nature), no thrills\n7. Systolic — occurs during and is limited to systole\n\nWith the presence of either of the following, the murmur is pathologic:\n\n¢ Grade 3/6 or higher murmurs\n\n¢ Harsh quality\n\n¢ Abnormal S2\n\n¢ The presence of a systolic click\n\n¢ Increased intensity with decreased venous return (e.g., when the patient stands)\n\n¢ The patient has any symptoms that could be related to a cardiac condition (e.g. shortness of breath, chest pain, poor feeding, etc.)\n\nIn the following situations, the patient should be referred to a pediatric cardiologist:\n\n¢ Murmurs in infancy, especially in the first 6 months\n\n¢ There is a family history of sudden cardiac death or congenital heart disease\n\n¢ There are cardiac symptoms — shortness of breath, poor feeding, failure to thrive, chest pain, fatigability, etc.\n¢ There are chromosomal abnormalities\n\n¢ The diagnosis is equivocal\n\nThis child is completely healthy and has no associated physical finding suggestive of a cardiac pathology. The murmur itself, on the other hand, has all characteristic features of an\ninnocent physiologic murmur, but since she is in the infancy period, referral to a specialist (preferably a pediatric cardiologist) is the most appropriate option to consider.\n\n(Option A) Chest X-ray and electrocardiography are of little value in assessment of the underlying cause of a murmur in a child. Chest X-rays were obtained previously as a part of\nassessment, but not an acceptable practice today.\n\n(Option C) Although this murmur is likely to be innocent, parents cannot be reassured unless full evaluation by a pediatric cardiologist excludes any pathologic etiology.\n(Option D) Echocardiography is the investigation of choice that may be considered by the pediatric cardiologist for further assessment.\n\n(Option E) Although parents should be informed of all possibilities, telling them that their baby has heart disease while the murmur is more likely to be innocent and no further assessment\nhas been carried out is not appropriate.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","diabetes","duration"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d84fba4f1f42ce4b7d452ba57ff872812e8970c8","duplicate_group_id":"exact-d84fba4f1f42","duplicate_sources":[{"record_id":"9b40e207fb32f27aae2f","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":125,"source_qid":null},{"record_id":"9dbc042c981c43d80c11","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":105,"source_qid":null},{"record_id":"280f9f65fabbab50a70f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1266,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
