INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a64bbe9c478ea2343c34','Pediatric amedex 2025.pdf','126','Paediatrics','Paul, aged 4 months, is diagnosed with pertussis. The father is an engineer and the mother a housewife. They both have completed childhood vaccination against
pertussis. Paul has a 5-year-old sister. Which one of the following is the most appropriate management plan to consider for Paul''s parents regarding pertussis?','{"A":"OA. Immediate booster immunization against pertussis.","B":"B. A 10-day course of erythromycin.","C":"C. Scheduling a 3-dose course of pertussis vaccination.","D":"D. Nasopharyngeal swabs.","E":"E. Immediate immunization with pertussis immunoglobulin."}','A','Current guidelines in Australia for the public health management of pertussis recommend Antibiotic treatment of the index case with exclusion from childcare,
school, work, or other environment where high-risk contacts may be present, until they are non-infectious (that is, after 5 days of antibiotic treatment). Treatment
must be commenced in the first 21 days of illness to be effective. It does not shorten the duration of the illness, but does limit duration of infectivity.

Chemoprophylaxis of contacts to prevent secondary transmission is not recommended in most situations because of the delayed presentation of the index case,
and the cost and adverse effects of antibiotics. However, given the high risk of mortality and morbidity associated with infection of the newborn, particularly in the
context of the rising incidence of pertussis in the community and the high transmission rate, chemoprophylaxis is recommended to limit transmission to those most
at risk of the infection. Data to support this recommendation are limited.

Australian guidelines recommend post-exposure chemoprophylaxis for contacts to whom transmission is most likely, and when there is significant risk of morbidity
or mortality or risk of transmission to other high-risk groups.

The following criteria must be met for commencement of prophylactic antibiotics:

¢ Close contact with confirmed case of pertussis (index case) while index case is infectious, which is within the first 21 days of cough and <5 days of
antibiotics

AND

¢ First contact was within 14 days (or within 21 days for infants <6 months) — beyond that time prophylaxis is not effective
If the above criteria are met, the following groups should receive prophylactic antibiotics:

Children

¢ Age <6 months; OR

e <3 doses pertussis vaccine; OR

¢ There is a household member aged <6 months; OR

¢ Children who attend childcare in same room as infant <6 months

Adults (regardless of immunization status)

¢ Expectant parents in last month of pregnancy; OR

¢ Health care worker in maternity hospital or newborn nursery; OR
¢ Childcare worker in close contact with infants <6 months; OR

¢ Household member aged <6 months

In the given scenario, there is no other child less than 6 months in the house other than Paul who is the index case, and none of the parents are in close contacts
with other children younger 6 than months, no prophylactic antibiotic is required; however, it is recommended that close contacts that are not up-to-date with their
pertussis immunization should be given DTPa or dTpa as soon after exposure as possible. dTpa should be considered for adults who have not had pertussis-
containing vaccine in the last 10 years.

(Option B) Parents do not fulfill criteria to receive prophylactic antibiotics.
(Option C) Parents have received their 3 doses in childhood and do not need to have it repeated again. All they need is a booster dose of pertussis vaccine.
(Option D) Nasopharyngeal swab results do not affect the management of close contacts in terms of prophylaxis; therefore, not indicated.

(Option E) Immunoglobulin (passive immunity) is not effective in reducing the chance of catching pertussis.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[126],"source_qid":null,"duplicate_group_id":"exact-bdcd552c2cca","duplicate_sources":[{"record_id":"a64bbe9c478ea2343c34","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":126,"source_qid":null},{"record_id":"ef382df2b16a0e84c317","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":45,"source_qid":null},{"record_id":"60fcb25bc575736e6b89","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":46,"source_qid":null},{"record_id":"97d4cb713dbd23a0b791","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1295,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"a64bbe9c478ea2343c34","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":126,"supporting_pages":[126],"source_qid":null,"domain_hint":"Paediatrics","stem":"Paul, aged 4 months, is diagnosed with pertussis. The father is an engineer and the mother a housewife. They both have completed childhood vaccination against\npertussis. Paul has a 5-year-old sister. Which one of the following is the most appropriate management plan to consider for Paul''s parents reg