INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1afb124d843d1696d495','Pediatric amedex 2025.pdf','127','Paediatrics','A 7-year-old boy weighs 30 kg and has a body mass index of 19.5 kg/m. Which one of the following is correct regarding his weight and BMI (use the following chart
for calculation)?',NULL,'D','Since the body composition changes with normal growth and stage of puberty, BMI in children is not a fixed measure like it is in adults. BMI interpretation in children
2-18 years of age must be plotted on the sex-specific BMI percentile charts. A 17-year-old boy with a BMI of 20 kg/m? is within the normal range while a 6-year-old
boy with the same BMI is obese.

To check the weight status of a child, his/her BMI should be calculated by dividing the weight by the square of the height in meter. The BMI then should be plotted on
the sex-specific BMI percentile to see in which zone it is. This child’s BMI lies in the ‘obesity’ zone (see the chart below).

Obese weary
Overweight [= Underweight

Captclick to enlarge

If used with the sex-specific percentile chart, BMI can be used for children with the same efficacy as for adults.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[127],"source_qid":null,"duplicate_group_id":"exact-013629f2f3e6","duplicate_sources":[{"record_id":"1afb124d843d1696d495","record_type":"visual_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":127,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/Pediatric_amedex_2025__fe3883efd6a6/page_00127.jpg","asset_preview_url":"https://drive.google.com/file/d/1D-lrFbn1-MZR6hxmDOHVInIryULG7Ojv/preview"}','visual_assets/Pediatric_amedex_2025__fe3883efd6a6/page_00127.jpg','https://drive.google.com/thumbnail?id=1D-lrFbn1-MZR6hxmDOHVInIryULG7Ojv&sz=w1600','source_page_image',NULL,'needs_verification','[]','low','{"record_id":"1afb124d843d1696d495","record_type":"visual_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":127,"supporting_pages":[127],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 7-year-old boy weighs 30 kg and has a body mass index of 19.5 kg/m. Which one of the following is correct regarding his weight and BMI (use the following chart\nfor calculation)?","options":null,"options_mode":"source_page_image","visual_asset":"visual_assets/Pediatric_amedex_2025__fe3883efd6a6/page_00127.jpg","source_answer":"D","source_explanation":"Since the body composition changes with normal growth and stage of puberty, BMI in children is not a fixed measure like it is in adults. BMI interpretation in children\n2-18 years of age must be plotted on the sex-specific BMI percentile charts. 