INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f2879502fd53cf0beb9e','Pediatric amedex 2025.pdf','128','Paediatrics','A 2-year-old boy is brought to the Emergency Department by his parents, who are concerned about his fever
and difficulty breathing. The fever has started this afternoon. On examination, he looks ill and pale and is
grunting. He has a temperature of 39.6°C and his respiration is shallow with a rate of 38 breaths per minute.
Chest auscultation is normal. Which one of following could be the most likely diagnosis?','{"A":"OA. Lobar pneumonia.","B":"B. Acute bronchitis.","C":"C. Atypical pneumonia.","D":"D. Bronchiolitis.","E":"E. Foreign body aspiration."}','A','The findings of a high fever associated with pallor and respiratory distress in an infant is strongly suggestive
of lobar pneumonia. In this age group, chest auscultation may deceitfully be normal due to shallow rapid
breathing and grunting. The chest X-ray, however, will show consolidation. The most common causative
organism is this situation would be streptococcus pneumoniae.

(Option B) Acute bronchitis has a more insidious onset and the child is not often as severely ill as this child.

(Option C) With atypical pneumonia, a prodromal state and more insidious onset is expected. Moreover,
fever is not often that high.

(Option D) Bronchiolitis is the viral infection of bronchioles, caused by respiratory syncytial virus (RSV) in
most cases, and is more commonly seen in infants younger than 12 months. There may be low-grade fever,
wheezing, bilateral fine crackles and respiratory distress. There is a prodrome of cough and rhinorrhea,
followed by more severe symptoms in the following 3 to 5 days. The high fever and acute onset of symptoms
favors the diagnosis of pneumonia rather than bronchiolitis.

(Option E) Although post-obstructive atelectasis can give rise to pneumonia in children with foreign body
aspiration, this usually occurs over a course of weeks. The respiratory symptoms such as unilateral
wheezing would be evident.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[128],"source_qid":"335","duplicate_group_id":"exact-8112088e0e28","duplicate_sources":[{"record_id":"f2879502fd53cf0beb9e","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":128,"source_qid":"335"},{"record_id":"1ea71a38b8d3c6a45640","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":35,"source_qid":null},{"record_id":"a1272519696b147b1bd5","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":36,"source_qid":null},{"record_id":"4819c700a90215a11379","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1251,"source_qid":"335"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"f2879502fd53cf0beb9e","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":128,"supporting_pages":[128],"source_qid":"335","domain_hint":"Paediatrics","stem":"A 2-year-old boy is brought to the Emergency Department by his parents, who are concerned about his fever\nand difficulty breathing. The fever has started this afternoon. On examination, he looks ill and pale and is\ngrunting. He has a temperature of 39.6°C and his respiration is shallow with a rate of 38 breaths per minute.\nChest auscultation is normal. Which one of following could be the most likely diagnosis?","options":{"A":"OA. Lobar pneumonia.","B":"B. Acute bronchitis.","C":"C. Atypical pneumonia.","D":"D. Bronchiolitis.","E":"E. Foreign body aspiration."},"source_answer":"A","source_explanation":"The findings of a high fever associated with pallor and respiratory distress in an infant is strongly suggestive\nof lobar pneumonia. In this age group, chest auscultation may deceitfully be normal due to shallow rapid\nbreathing and grunting. The chest X-ray, however, will show consolidation. The most common causative\norganism is this situation would be streptococcus pneumoniae.\n\n(Option B) Acute bronchitis has a more insidious onset and the child is not often as severely ill as this child.\n\n(Option C) With atypical pneumonia, a prodromal state and more insidious onset is expected. Moreover,\nfever is not often that high.\n\n(Option D) Bronchiolitis is the viral infection of bronchioles, caused by respiratory syncytial virus (RSV) in\nmost cases, and is more commonly seen in infants younger than 12 months. There may be low-grade fever,\nwheezing, bilateral fine crackles and respiratory distress. There is a prodrome of cough and rhinorrhea,\nfollowed by more severe symptoms in the following 3 to 5 days. The high fever and acute onset of symptoms\nfavors the diagnosis of pneumonia rather than bronchiolitis.\n\n(Option E) Although post-obstructive atelectasis can give rise to pneumonia in children with foreign body\naspiration, this usually occurs over a course of weeks. The respiratory symptoms such as unilateral\nwheezing would be evident.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"8112088e0e28df4348890b295f2d581216d2d561","duplicate_group_id":"exact-8112088e0e28","duplicate_sources":[{"record_id":"f2879502fd53cf0beb9e","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":128,"source_qid":"335"},{"record_id":"1ea71a38b8d3c6a45640","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":35,"source_qid":null},{"record_id":"a1272519696b147b1bd5","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":36,"source_qid":null},{"record_id":"4819c700a90215a11379","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1251,"source_qid":"335"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
