INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('f2879502fd53cf0beb9e','src-v294-5083b15f','335','128','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','A 2-year-old boy is brought to the Emergency Department by his parents, who are concerned about his fever
and difficulty breathing. The fever has started this afternoon. On examination, he looks ill and pale and is
grunting. He has a temperature of 39.6°C and his respiration is shallow with a rate of 38 breaths per minute.
Chest auscultation is normal. Which one of following could be the most likely diagnosis?',NULL,'A','The findings of a high fever associated with pallor and respiratory distress in an infant is strongly suggestive
of lobar pneumonia. In this age group, chest auscultation may deceitfully be normal due to shallow rapid
breathing and grunting. The chest X-ray, however, will show consolidation. The most common causative
organism is this situation would be streptococcus pneumoniae.

(Option B) Acute bronchitis has a more insidious onset and the child is not often as severely ill as this child.

(Option C) With atypical pneumonia, a prodromal state and more insidious onset is expected. Moreover,
fever is not often that high.

(Option D) Bronchiolitis is the viral infection of bronchioles, caused by respiratory syncytial virus (RSV) in
most cases, and is more commonly seen in infants younger than 12 months. There may be low-grade fever,
wheezing, bilateral fine crackles and respiratory distress. There is a prodrome of cough and rhinorrhea,
followed by more severe symptoms in the following 3 to 5 days. The high fever and acute onset of symptoms
favors the diagnosis of pneumonia rather than bronchiolitis.

(Option E) Although post-obstructive atelectasis can give rise to pneumonia in children with foreign body
aspiration, this usually occurs over a course of weeks. The respiratory symptoms such as unilateral
wheezing would be evident.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[128],"source_qid":"335","duplicate_group_id":"exact-8112088e0e28","duplicate_sources":[{"record_id":"f2879502fd53cf0beb9e","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":128,"source_qid":"335"},{"record_id":"1ea71a38b8d3c6a45640","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":35,"source_qid":null},{"record_id":"a1272519696b147b1bd5","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":36,"source_qid":null},{"record_id":"4819c700a90215a11379","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1251,"source_qid":"335"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excl