INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('62bf8c182e47b219a1fb','Pediatric amedex 2025.pdf','129','Paediatrics','Regarding patent ductus arteriosus, which one of the following statements is incorrect?','{"A":"A. It frequently occurs as an isolated phenomenon.","B":"OB. Cyanosis is usually present.","C":"C. It causes a pansystolic ‘machinery’ murmur at the left sternal border.","D":"D. There is a wide pulse pressure.","E":"E. Definite treatment is often by surgical closure."}','B','During fetal life, ductus arteriosus, a conduit connecting the pulmonary artery to the proximal descending
aorta, is patent (open). This patency is vital to the fetus because it allows most of the blood from the right
heart to bypass the fetal fluid-filled lungs and enter the aorta, and from there, flow into the systemic
circulation. After birth and when the neonate should take over breathing and oxygenation, it is essential for
ductus arteriosus to close for prevention of mixing oxygenated and deoxygenated blood; otherwise, a shunt of
oxygenated blood from higher-pressure aorta to the lower-pressure pulmonary artery will occur. With left-to-
right shunts, such as in patent ductus arteriosus, cyanosis is not a feature until very late in the course of the
disease.

(Option A) Patent ductus arteriosus (PDA) is often an isolated congenital cardiac problem with no association
with other cardiac anomalies.

(Option B) PDA is associated with left-to-right shunting; therefore, cyanosis would not be a presenting
feature; however, if untreated, right-to-left shunting and cyanosis eventually follows.

(Option D) Small lesions are expected to be asymptomatic, but larger ones present with bounding (strong)
arterial pulses, wide pulse pressure, the typical systolic machinery murmur, and congestive heart failure in
severe or prolonged cases.

(Option E) In some cases, PDA closure occurs spontaneously within one week. Lesions persisting beyond
one week are very unlikely to close on their own. NSAIDs, by inhibiting prostaglandin synthesis play a role in
management; nonetheless, closure by surgical intervention is needed for cases with persisting PDA.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[129],"source_qid":null,"duplicate_group_id":"exact-74f78bfa9195","duplicate_sources":[{"record_id":"62bf8c182e47b219a1fb","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":129,"source_qid":null},{"record_id":"f81f3c94ab4812c6e738","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":183,"source_qid":null},{"record_id":"e20e3f23983e56791516","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":182,"source_qid":null},{"record_id":"9c53fde107f9c25aadb4","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1269,"source_qid":"100"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"62bf8c182e47b219a1fb","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":129,"supporting_pages":[129],"source_qid":null,"domain_hint":"Paediatrics","stem":"Regarding patent ductus arteriosus, which one of the following statements is incorrect?","options":{"A":"A. It frequently occurs as an isolated phenomenon.","B":"OB. Cyanosis is usually present.","C":"C. It causes a pansystolic ‘machinery’ murmur at the left sternal border.","D":"D. There is a wide pulse pressure.","E":"E. Definite treatment is often by surgical closure."},"source_answer":"B","source_explanation":"During fetal life, ductus arteriosus, a conduit connecting the pulmonary artery to the proximal descending\naorta, is patent (open). This patency is vital to the fetus because it allows most of the blood from the right\nheart to bypass the fetal fluid-filled lungs and enter the aorta, and from there, flow into the systemic\ncirculation. After birth and when the neonate should take over breathing and oxygenation, it is essential for\nductus arteriosus to close for prevention of mixing oxygenated and deoxygenated blood; otherwise, a shunt of\noxygenated blood from higher-pressure aorta to the lower-pressure pulmonary artery will occur. With left-to-\nright shunts, such as in patent ductus arteriosus, cyanosis is not a feature until very late in the course of the\ndisease.\n\n(Option A) Patent ductus arteriosus (PDA) is often an isolated congenital cardiac problem with no association\nwith other cardiac anomalies.\n\n(Option B) PDA is associated with left-to-right shunting; therefore, cyanosis would not be a presenting\nfeature; however, if untreated, right-to-left shunting and cyanosis eventually follows.\n\n(Option D) Small lesions are expected to be asymptomatic, but larger ones present with bounding (strong)\narterial pulses, wide pulse pressure, the typical systolic machinery murmur, and congestive heart failure in\nsevere or prolonged cases.\n\n(Option E) In some cases, PDA closure occurs spontaneously within one week. Lesions persisting beyond\none week are very unlikely to close on their own. NSAIDs, by inhibiting prostaglandin synthesis play a role in\nmanagement; nonetheless, closure by surgical intervention is needed for cases with persisting PDA.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"74f78bfa91950d60858f39bed55d6c85a85f9b38","duplicate_group_id":"exact-74f78bfa9195","duplicate_sources":[{"record_id":"62bf8c182e47b219a1fb","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":129,"source_qid":null},{"record_id":"f81f3c94ab4812c6e738","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":183,"source_qid":null},{"record_id":"e20e3f23983e56791516","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":182,"source_qid":null},{"record_id":"9c53fde107f9c25aadb4","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1269,"source_qid":"100"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
