INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c83244f519283b805d4e','Pediatric amedex 2025.pdf','130','Paediatrics','A 5-month-old child is brought to your practice with a 10-day history of cough paroxysms followed by inspiratory whoop
and vomiting. There is no cyanosis associated with bouts of cough, and the child is well between the attacks. Which
one of the following is the most appropriate action now?','{"A":"A. Reassure.","B":"B. Prescribe a 5-day course of antibiotics and discharge the child home.","C":"OC. Admit the child to the hospital for observation.","D":"D. Chemoprophylaxis of the household.","E":"E. Vaccinate the household."}','C','The clinical picture is consistent with whooping cough (pertussis) caused by Bordetella pertussis.

Pertussis is a prolonged coughing illness with varying clinical manifestations depending on age and immunization
status. An initial catarrhal phase is characterized by insidious onset of runny nose, sneezing absent or low-grade fever,
and a mild occasional cough. The cough gradually becomes paroxysmal usually after 1-2 weeks, and may end in
vomiting, cyanosis, and/or a characteristic high-pitched inspiratory whoop. Paroxysms can recur with subsequent
respiratory illnesses for many months after the onset of pertussis. Fever is generally minimal or absent throughout the
course of the disease. Infants are less likely to have the inspiratory whoop and a significant catarrhal phase and are
more likely to present with gagging, gasping, cyanosis, apnea or non-specific signs such as poor feeding or seizures.

Current Guidelines in Australia recommend that the following patients with pertussis are admitted and managed in
hospital:

¢ Infants less than 6 months of age
¢ Any child with complications (i.e. apnea, cyanosis, pneumonia, encephalopathy)

Since this child is younger than 6 months, admission to hospital and further management is the most appropriate next
step.

Antibiotics are indicated only in the following situations:

¢ The patient is diagnosed in catarrhal or early paroxysmal phase (may reduce severity)
¢ Cough for less than 14 days (may reduce spread; reduces school exclusion period)

¢ The patient is admitted to hospital

¢ There are complications (e.g., pneumonia, cyanosis, or apnea)

After admission, this child will require antibiotics as well, but this not take precedence over hospital admission.
Azithromycin is an appropriate option.

Chemoprophylaxis would have been indicated if there was a child <6 months or someone with <3 doses of vaccine
among the household (besides the index case). Catching up with immunization, at a later date, should be encouraged
even if the child has had pertussis, but this step is not a part of acute management.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[130],"source_qid":null,"duplicate_group_id":"exact-1cd192598da2","duplicate_sources":[{"record_id":"c83244f519283b805d4e","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":130,"source_qid":null},{"record_id":"8bc82186d7f3b5b25cff","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":186,"source_qid":null},{"record_id":"1c68eea05324a5e19ab3","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":187,"source_qid":null},{"record_id":"9de981521b488a18fb57","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1303,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"c83244f519283b805d4e","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":130,"supporting_pages":[130],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 5-month-old child is brought to your practice with a 10-day history of cough paroxysms followed by inspiratory whoop\nand vomiting. There is no cyanosis associated with bouts of cough, and the child is well between the attacks. Which\none of the following is the most appropriate action now?","options":{"A":"A. Reassure.