INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5cf3706ec555c6b57a6e','Pediatric amedex 2025.pdf','131','Paediatrics','A 6-month-old male infant with Tetralogy of Fallot (TF) is brought to your clinic by his mother with history of nasal discharge, low-grade fever,
feeding difficulty, wheezy breathing, and cough for 3 days. The infant''s father smokes a pack of cigarettes per day at home. Physical examination
is significant for inspiratory crackles and expiratory wheeze. Respiratory rate is 60 breaths per minute and oxygen saturation is 92 % on room air.
Which one of the following is the next best step in management?','{"A":"A. Reassure the mother and educate about minimal handling and frequent feeds.","B":"OB. Admit the baby to the hospital and consider symptomatic care with supplemental oxygen, minimal handling and use of intravenous fluids.","C":"C. Start corticosteroid therapy immediately.","D":"D. Start nebulized ribavirin and monitor the response.","E":"E. Start the child on nebulized saline 3% immediately."}','B','This infant has clinical diagnosis of acute viral bronchiolitis. The diagnosis of bronchiolitis is clinical and based on typical history of increased
respiratory rate, cough, expiratory wheezing and bilateral fine crackles, preceded by a prodromal syndrome of low-grade fever and rhinorrhea.

For children with increased risk of progression to severe bronchiolitis, special consideration and probably admission to the hospital and discussion
with a senior doctor is required. Such infants are those with:

¢ History of significant apnea before assessment

¢ Known structural cardiac anomaly, especially large left-to-right shunt (e.g., ventricular septal defect)
¢ Known pre-existing lung disease (e.g., cystic fibrosis)

¢ Age less than 6 weeks

¢ Significant prematurity (< 32 weeks) and/or chronic neonatal lung disease

¢ Severe degree of respiratory distress or apnea

¢ Significant dehydration

¢ Hypoxemia (Spo2 < 93%)

e Re-presentation to the emergency department within 24 hours

e Uncertain diagnosis.

In the following situations, hospital admission is definitely indicated:

¢ Difficulty in feeding

¢ Increased work of breathing - use of accessory respiratory muscles
e Respiratory rate>50 breaths per minute

¢ Oxygen saturation less than 93% on room air.

e Apnea

¢ Dehydration

¢ Patient or parental exhaustion

This child has SpO2 of 92% and a breathing rate of 60 breaths per minute. He also has as an underlying congenital heart disease. For him,
hospital admission is the first thing to consider.

The main issues in management are parental reassurance, education about minimal handling, and frequent feeds. The child should receive
intravenous fluids because the illness itself, as well as tachypnea makes the child dehydrated.

(Option A) Although mentioned measures are appropriate, these should be taken in the hospital after admission. This option does not include
hospital admission and is not correct.

(Option C) Corticosteroids have not shown any benefit in management of bronchiolitis.

(Option D) Nebulized ribavirin may be used in immunocompromised patients but only provides marginal benefit in respiratory syncytial virus
infection. It is expensive, potentially toxic, and rarely indicated. Its use is not recommended without specialist consultation.

(Option E) There is some evidence that the use of inhaled 3 % hypertonic saline may reduce the length of stay in hospital and improve clinical
severity score; however, it is not considered first-line treatment and its use remains controversial.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[131],"source_qid":null,"duplicate_group_id":"exact-160c84308bab","duplicate_sources":[{"record_id":"5cf3706ec555c6b57a6e","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":131,"source_qid":null},{"record_id":"25099b588f0f2df3ebd9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1255,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"5cf3706ec555c6b57a6e","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":131,"supporting_pages":[131],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 6-month-old male infant with Tetralogy of Fallot (TF) is brought to your clinic by his mother with history of nasal discharge, low-grade fever,\nfeeding difficulty, wheezy breathing, and cough for 3 days. The infant''s father smokes a pack of cigarettes per day at home. Physical examination\nis significant for inspiratory crackles and expiratory wheeze. Respiratory rate is 60 breaths per minute and oxygen saturation is 92 % on room air.\nWhich one of the following is the next best step in management?","options":{"A":"A. Reassure the mother and educate about minimal handling and frequent feeds.","B":"OB. Admit the baby to the hospital and consider symptomatic care with supplemental oxygen, minimal handling and use of intravenous fluids.","C":"C. Start corticosteroid therapy immediately.","D":"D. Start nebulized ribavirin and monitor the response.","E":"E. Start the child on nebulized saline 3% immediately."},"source_answer":"B","source_explanation":"This infant has clinical diagnosis of acute viral bronchiolitis. The diagnosis of bronchiolitis is clinical and based on typical history of increased\nrespiratory rate, cough, expiratory wheezing and bilateral fine crackles, preceded by a prodromal syndrome of low-grade fever and rhinorrhea.\n\nFor children with increased risk of progression to severe bronchiolitis, special consideration and probably admission to the hospital and discussion\nwith a senior doctor is required. Such infants are those with:\n\n¢ History of significant apnea before assessment\n\n¢ Known structural cardiac anomaly, especially large left-to-right shunt (e.g., ventricular septal defect)\n¢ Known pre-existing lung disease (e.g., cystic fibrosis)\n\n¢ Age less than 6 weeks\n\n¢ Significant prematurity (< 32 weeks) and/or chronic neonatal lung disease\n\n¢ Severe degree of respiratory distress or apnea\n\n¢ Significant dehydration\n\n¢ Hypoxemia (Spo2 < 93%)\n\ne Re-presentation to the emergency department within 24 hours\n\ne Uncertain diagnosis.\n\nIn the following situations, hospital admission is definitely indicated:\n\n¢ Difficulty in feeding\n\n¢ Increased work of breathing - use of accessory respiratory muscles\ne Respiratory rate>50 breaths per minute\n\n¢ Oxygen saturation less than 93% on room air.\n\ne Apnea\n\n¢ Dehydration\n\n¢ Patient or parental exhaustion\n\nThis child has SpO2 of 92% and a breathing rate of 60 breaths per minute. He also has as an underlying congenital heart disease. For him,\nhospital admission is the first thing to consider.\n\nThe main issues in management are parental reassurance, education about minimal handling, and frequent feeds. The child should receive\nintravenous fluids because the illness itself, as well as tachypnea makes the child dehydrated.\n\n(Option A) Although mentioned measures are appropriate, these should be taken in the hospital after admission. This option does not include\nhospital admission and is not correct.\n\n(Option C) Corticosteroids have not shown any benefit in management of bronchiolitis.\n\n(Option D) Nebulized ribavirin may be used in immunocompromised patients but only provides marginal benefit in respiratory syncytial virus\ninfection. It is expensive, potentially toxic, and rarely indicated. Its use is not recommended without specialist consultation.\n\n(Option E) There is some evidence that the use of inhaled 3 % hypertonic saline may reduce the length of stay in hospital and improve clinical\nseverity score; however, it is not considered first-line treatment and its use remains controversial.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"160c84308bab387c08651f78ee965e68e17ad39c","duplicate_group_id":"exact-160c84308bab","duplicate_sources":[{"record_id":"5cf3706ec555c6b57a6e","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":131,"source_qid":null},{"record_id":"25099b588f0f2df3ebd9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1255,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
