INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('5cf3706ec555c6b57a6e','src-v294-5083b15f',NULL,'131','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','A 6-month-old male infant with Tetralogy of Fallot (TF) is brought to your clinic by his mother with history of nasal discharge, low-grade fever,
feeding difficulty, wheezy breathing, and cough for 3 days. The infant''s father smokes a pack of cigarettes per day at home. Physical examination
is significant for inspiratory crackles and expiratory wheeze. Respiratory rate is 60 breaths per minute and oxygen saturation is 92 % on room air.
Which one of the following is the next best step in management?',NULL,'B','This infant has clinical diagnosis of acute viral bronchiolitis. The diagnosis of bronchiolitis is clinical and based on typical history of increased
respiratory rate, cough, expiratory wheezing and bilateral fine crackles, preceded by a prodromal syndrome of low-grade fever and rhinorrhea.

For children with increased risk of progression to severe bronchiolitis, special consideration and probably admission to the hospital and discussion
with a senior doctor is required. Such infants are those with:

¢ History of significant apnea before assessment

¢ Known structural cardiac anomaly, especially large left-to-right shunt (e.g., ventricular septal defect)
¢ Known pre-existing lung disease (e.g., cystic fibrosis)

¢ Age less than 6 weeks

¢ Significant prematurity (< 32 weeks) and/or chronic neonatal lung disease

¢ Severe degree of respiratory distress or apnea

¢ Significant dehydration

¢ Hypoxemia (Spo2 < 93%)

e Re-presentation to the emergency department within 24 hours

e Uncertain diagnosis.

In the following situations, hospital admission is definitely indicated:

¢ Difficulty in feeding

¢ Increased work of breathing - use of accessory respiratory muscles
e Respiratory rate>50 breaths per minute

¢ Oxygen saturation less than 93% on room air.

e Apnea

¢ Dehydration

¢ Patient or parental exhaustion

This child has SpO2 of 92% and a breathing rate of 60 breaths per minute. He also has as an underlying congenital heart disease. For him,
hospital admission is the first thing to consider.

The main issues in management are parental reassurance, education about minimal handling, and frequent feeds. The child should receive
intravenous fluids because the illness itself, as well as tachypnea makes the child dehydrated.

(Option A) Although mentioned measures are appropriate, these should be taken in the hospital after admission. This option does not include
hospital admission and is not correct.

(Option C) Corticosteroids have not shown any benefit in management of bronchiolitis.

(Option D) Nebulized ribavirin may be used in immunocompromised patients but only provides marginal benefit in respiratory syncytial virus
infection. It is expensive, potentially toxic, and rarely indicated. Its use is not recommended without specialist consultation.

(Option E) There is some evidence that the use of inhaled 3 % hypertonic saline may reduce the length of stay in hospital and improve clinical
severity score; however, it is not considered first-line treatment and its use remains controversial.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[131],"source_qid":null,"duplicate_group_id":"exact-160c84308bab","duplicate_sources":[{"record_id":"5cf3706ec555c6b57a6e","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":131,"source_qid":null},{"record_id":"25099b588f0f2df3ebd9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1255,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
