INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d4c0689b0ef98b6c35b6','Pediatric amedex 2025.pdf','132','Paediatrics','Parents of a 12-year-old girl has brought her to a clinic after they noticed a rash on hers back. She had sore throat 3 weeks ago which subsided gradually in a
course of days. Last week she had a very painful left wrist pain that improved after 2 days before she develops pain in her right knee. Today, she has a painful
right ankle. On physical examination, she looks ill and has a temperature of 38.1°C. The rest of her vital signs are within normal limits. Examination of the
musculoskeletal system is notable for a painful, slightly hot and swollen right ankle with decreased range of motion due to pain. There is a rash on her back which
is shown in the following photograph. Which one of the following is the most appropriate next step in management?','{"A":"A. Echocardiography.","B":"B. Blood culture.","C":"C. ESR.","D":"OD. Throat swab.","E":"E. Full blood examination (FBE)."}','D','The photograph shows well demarcated bright red and pink macules characteristic of erythema marginatum. The presence of the rash, migratory
arthralgia/arthritis (involvement of one joint, improvement and then involvement of another joint), and more importantly, a history of sore throat 3 weeks before
such presentation is highly suggestive of acute rheumatic fever as the most likely diagnosis.

Acute rheumatic fever (ARF) occurs predominantly in childhood and is secondary to infection with Group A streptococcus (GAS). It is an acute illness presenting
with a cluster of signs and symptoms including carditis and polyarthralgia. Without preventive treatment, ARF may progress to chronic rheumatic heart disease
(RHD) associated with damaged heart valves.

An accurate diagnosis of ARF is important because overdiagnosis results in unnecessary treatment over a long time, while underdiagnosis leads to further attacks
of ARF, cardiac damage and premature death. Diagnosis is mostly clinical because there is no specific laboratory test.

The diagnosis of ARF is usually guided by the Jones criteria and the more recent World Health Organization (WHO) criteria. To increase sensitivity for ARF
diagnosis in Australia’s unique high-risk population, the Jones and WHO criteria have been further modified to form the 2012 Australian criteria for the diagnosis.
According to Australian guidelines, aseptic monoarthritis or polyarthralgia is a major criteria for populations at risk, including Aboriginal and Torres Strait Islanders
communities living in rural or remote areas or in disadvantaged suburban areas, it is a minor criteria (in agreement with international guidelines) for other not-at-
risk populations.

The following table summarizes the Australian ARF diagnostic criteria for high risk population and other populations:

Carditis (including subclinical Carditis (including subclinical
evidence of rheumatic valve disease evidence of rheumatic valve disease
on echocardiogram) on echocardiogram)

Polyarthritis or aseptic mono-arthritis Polyarthritis

or polyarthralgia Sydenham chorea

Sydenham chorea Erythema marginatum

Erythema marginatum Subcutaneous nodules
Subcutaneous nodules

Minor criteria Minor criteria

Fever Polyarthralgia or aseptic mono-

ESR 230 mm/hr or CRP 230 mg/L arthritis

Prolonged P-R interval on ECG ESR 230 mm/hr or CRP 230 mg/L
Prolonged P-R interval on ECG','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[132],"source_qid":null,"duplicate_group_id":"exact-d765e1a9a115","duplicate_sources":[{"record_id":"d4c0689b0ef98b6c35b6","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":132,"source_qid":null},{"record_id":"0f9efe4a28e69d2e7cb2","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":8,"source_qid":null},{"record_id":"b18bec550312e0c82081","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1375,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"d4c0689b0ef98b6c35b6","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":132,"supporting_pages":[132],"source_qid":null,"domain_hint":"Paediatrics","stem":"Parents of a 12-year-old girl has brought her to a clinic after they noticed a rash on hers back. She had sore throat 3 weeks ago which subsided gradually in a\ncourse of days. Last week she had a very painful left wrist pain that improved after 2 days before she develops pain in her right knee. Today, she has a painful\nright ankle. On physical examination, she looks ill and has a temperature of 38.1°C. The rest of her vital signs are within normal limits. Examination of the\nmusculoskeletal system is notable for a painful, slightly hot and swollen right ankle with decreased range of motion due to pain. There is a rash on her back which\nis shown in the following photograph. Which one of the following is the most appropriate next step in management?","options":{"A":"A. Echocardiography.","B":"B. Blood culture.","C":"C. ESR.","D":"OD. Throat swab.","E":"E. Full blood examination (FBE)."},"source_answer":"D","source_explanation":"The photograph shows well demarcated bright red and pink macules characteristic of erythema marginatum. The presence of the rash, migratory\narthralgia/arthritis (involvement of one joint, improvement and then involvement of another joint), and more importantly, a history of sore throat 3 weeks before\nsuch presentation is highly suggestive of acute rheumatic fever as the most likely diagnosis.\n\nAcute rheumatic fever (ARF) occurs predominantly in childhood and is secondary to infection with Group A streptococcus (GAS). It is an acute illness presenting\nwith a cluster of signs and symptoms including carditis and polyarthralgia. Without preventive treatment, ARF may progress to chronic rheumatic heart disease\n(RHD) associated with damaged heart valves.\n\nAn accurate diagnosis of ARF is important because overdiagnosis results in unnecessary treatment over a long time, while underdiagnosis leads to further attacks\nof ARF, cardiac damage and premature death. Diagnosis is mostly clinical because there is no specific laboratory test.\n\nThe diagnosis of ARF is usually guided by the Jones criteria and the more recent World Health Organization (WHO) criteria. To increase sensitivity for ARF\ndiagnosis in Australia’s unique high-risk population, the Jones and WHO criteria have been further modified to form the 2012 Australian criteria for the diagnosis.\nAccording to Australian guidelines, aseptic monoarthritis or polyarthralgia is a major criteria for populations at risk, including Aboriginal and Torres Strait Islanders\ncommunities living in rural or remote areas or in disadvantaged suburban areas, it is a minor criteria (in agreement with international guidelines) for other not-at-\nrisk populations.\n\nThe following table summarizes the Australian ARF diagnostic criteria for high risk population and other populations:\n\nCarditis (including subclinical Carditis (including subclinical\nevidence of rheumatic valve disease evidence of rheumatic valve disease\non echocardiogram) on echocardiogram)\n\nPolyarthritis or aseptic mono-arthritis Polyarthritis\n\nor polyarthralgia Sydenham chorea\n\nSydenham chorea Erythema marginatum\n\nErythema marginatum Subcutaneous nodules\nSubcutaneous nodules\n\nMinor criteria Minor criteria\n\nFever Polyarthralgia or aseptic mono-\n\nESR 230 mm/hr or CRP 230 mg/L arthritis\n\nProlonged P-R interval on ECG ESR 230 mm/hr or CRP 230 mg/L\nProlonged P-R interval on ECG","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","guideline","interval","management","treatment"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d765e1a9a11583fe47158f22405593a8bd54e610","duplicate_group_id":"exact-d765e1a9a115","duplicate_sources":[{"record_id":"d4c0689b0ef98b6c35b6","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":132,"source_qid":null},{"record_id":"0f9efe4a28e69d2e7cb2","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":8,"source_qid":null},{"record_id":"b18bec550312e0c82081","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1375,"source_qid":null}]}',1,'v2.9.4