Prolonged P-R interval on ECG ESR 230 mm/hr or CRP 230 mg/L
Prolonged P-R interval on ECG',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[132],"source_qid":null,"duplicate_group_id":"exact-d765e1a9a115","duplicate_sources":[{"record_id":"d4c0689b0ef98b6c35b6","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":132,"source_qid":null},{"record_id":"0f9efe4a28e69d2e7cb2","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":8,"source_qid":null},{"record_id":"b18bec550312e0c82081","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1375,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=