INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4ddbc7ba6c64ecfd57a0','Pediatric amedex 2025.pdf','134','Paediatrics','A 2-year-old boy is brought to the Emergency Department, at 11 pm, by his parents with complaints of a harsh barking cough. On
examination, he is febrile with a temperature of 39°C and has a respiratory rate of 32 breaths per minute. There is inspiratory
stridor as well as scattered crackles over both lung fields. He is easily irritated but can be consoled by the parents. Which one of
the following is most important to give him first?','{"A":"A. Intravenous prednisolone.","B":"B. Nebulized adrenaline.","C":"C. Nebulized salbutamol.","D":"OD. Oral steroids.","E":"E. Antibiotics."}','D','The age of the child, the fever, the harsh cough and more importantly the stridor is suggestive of croup until proven otherwise.
The term croup has been used to describe a variety of respiratory conditions in children, including:

e Laryngitis - Inflammation is limited to the larynx and manifests as hoarseness. It usually occurs in older children and adults
and, similar to croup, it is frequently caused by a viral infection.

e Laryngotracheitis - Refers to inflammation of the larynx and trachea. Although lower airway signs are absent, the typical
barking cough will be present.

e Laryngotracheobronchitis - The condition occurs when inflammation extends into the bronchi, resulting in lower airway signs
(e.g. wheezing, crackles, air trapping, tachypnea) and sometimes more severe illness than laryngotracheitis alone. This
term commonly is used interchangeably with laryngotracheitis, and the entities are often indistinct clinically. Further
extension of the inflammation into the lower airways results in laryngotracheobronchopneumonitis, which sometimes can be
complicated by bacterial superinfection. Bacterial superinfection can manifest as pneumonia, bronchopneumonia, or
bacterial tracheitis.

NOTE - Laryngotracheitis and laryngotracheobronchitis are the conditions that have been interchangeably considered as
classic croup.

¢ Bacterial tracheitis - Bacterial tracheitis (also called bacterial croup) describes bacterial infection of the subglottic trachea,
resulting in a thick, purulent exudate, which causes symptoms of upper airway obstruction. The bronchi and lungs are
typically involved, as well (i.e. bacterial tracheobronchitis). Bacterial tracheitis may occur as a complication of viral respiratory
infections or as a primary bacterial infection.

e Spasmodic croup - Spasmodic croup is characterized by the sudden onset of inspiratory stridor at night, short duration
(several hours), and sudden cessation. This is often in the setting of a mild upper respiratory infection, but without fever or
inflammation. A striking feature of spasmodic croup is its recurrent nature. Because of some clinical overlap with atopic
diseases, it is sometimes referred to as ‘allergic croup’.

Croup in most commonly seen in children aged 6 to 36 months of age. It is also seen in children as young as 3 months and
preschool children but rare beyond these age extremes.

Viruses are almost always the cause with parainfluenza virus type 1 being the most common culprit. Other common viruses are
respiratory syncytial virus (RSV), influenza virus, and rhinovirus. Bacterial croup can be primary, for which mycoplasma species
are the most common etiology, or secondary due to superinfection with staphylococcus aureus (most common cause of
superinfection), streptococcus pyogenes or streptococcus pneumoniae

The most common presentation is a harsh cough that in younger children takes the quality of barking, inspiratory stridor and
hoarseness. When the inflammation extends to involve the structures below the trachea, e.g. bronchi, crackles and wheezes may
be present as well. Fever is not a prominent feature; however, there may be a fever as high as 39°C, especially when the lower
parts of the respiratory tract are involved or when there is bacterial croup.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[134],"source_qid":null,"duplicate_group_id":"exact-37d0bc983631","duplicate_sources":[{"record_id":"4ddbc7ba6c64ecfd57a0","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":134,"source_qid":null},{"record_id":"99908205ad12274762c8","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":115,"source_qid":null},{"record_id":"e3c5b47e67dd4afb1fc1","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":116,"source_qid":null},{"record_id":"cb966bc8d768264c06aa","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1312,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"4ddbc7ba6c64ecfd57a0","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":134,"supporting_pages":[134],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 2-year-old boy is brought to the Emergency Department, at 11 pm, by his parents with complaints of a harsh barking cough. On\nexamination, he is febrile with a temperature of 39°C and has a respiratory rate of 32 breaths per minute. There is inspiratory\nstridor as well as scattered crackles over both lung fields. He is easil