INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5ceaa87eb1c2938099c9','Pediatric amedex 2025.pdf','136','Paediatrics','You are called by the nurse on duty to assess a 24-hour old female neonate in the neonatal ward. Physical examination is remarkable for the knees being at
unequal levels when the hips and knees are flexed, asymmetric gluteal folds, and limited abduction of the right hip. The history is significant for breech delivery.
Which one of the following is the most likely diagnosis?','{"A":"A. Osgood-Schlatter disease.","B":"Slipped capital femoral epiphysis.","C":"OC. Developmental dysplasia of the hip.","D":"D. Femoral head fracture.","E":"E. Legg-Calve-Perthes disease."}','C','The exam findings are characteristic of developmental dysplasia of the hip (DDH), also called congenital hip dislocation.

DDH can be unilateral or bilateral. Both genetic and environmental factors contribute to the condition. With positive family history, bilateral involvement is more
common. Genetic as well as environmental factors has been implicated for DD. Environemental factors include intrauterine malposition (especially breech with
extended legs) and maternal production of relaxin shortly before delivery (relaxin is a ligament-relaxing hormone)

Female newborns are 6 times more likely to be affected. Every newborn should be screened for the condition because if left untreated it can lead to disabling
morbidity.

DDH can present with the following features on examination:

¢ Diminished abduction in flexion of the affected hip

¢ Apparent inequality of legs with the affected leg being shortened and externally rotated
¢ Asymmetrical skin creases of the groin and thigh

¢ ‘clicking’ on hip movements

In DDH the femoral head of the affected side is subluxed, dislocatable or dislocated. This, if left untreated, leads to early degenerative joint disease of the hips.

Two tests are used to diagnose DDH:

Barlow test — The affected femoral head can be telescoped in and out of the acetabular socket by piston-like ‘telescoping’ movements in the long axis of the flexed
and abducted thighs. This maneuver is often done at the same time as Ortolani test. Great caution should be taken to avoid further ligamental injuries.

Ortolani test — The child’s flexed hips are abducted. The thighs are the grasped between the thumbs in front and other fingers behind. The child’s knees are flexed
and hip flexed to a right angle. Each thigh is steadily abducted towards the examining surface while the fingers behind apply forward pressure. Positive findings
include reduction of the dislocated femoral head into the acetabulum with an audible and palpable ‘jerk’ or ‘clunk’ (not a click). (Positive Ortolani sign)

NOTE - Barlow test is always performed before Ortolani test.

(Option A) Osgood-Schlatter disease is the overuse apophysitis of the tibial tubercle resulting in localized pain, especially with quadriceps contraction in active
young boys.

(Option B) Slipped capital femoral epiphysis is the separation of the proximal femoral epiphysis through the growth plate, possibly as a result of imbalance between
growth hormone and sex hormones, and often seen in early adolescence (the typical patient is an overweight boy of 10-14 years of age).

(Option D) With no history of trauma, femoral head fracture is unlikely. Furthermore, femoral head fracture presents differently.

(Option E) Legg-Calve-Perthes disease is an idiopathic avascular necrosis of the femoral head most commonly found in boys of 4 to 10 years of age.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[136],"source_qid":null,"duplicate_group_id":"exact-957afe0de637","duplicate_sources":[{"record_id":"5ceaa87eb1c2938099c9","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":136,"source_qid":null},{"record_id":"9891cf0de39877b06658","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":27,"source_qid":null},{"record_id":"09d34eb235553b4edd77","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":28,"source_qid":null},{"record_id":"0edbb93d3da5f5d01392","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1272,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"5ceaa87eb1c2938099c9","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":136,"supporting_pages":[136],"source_qid":null,"domain_hint":"Paediatrics","stem":"You are called by the nurse on duty to assess a 24-hour old female neonate in the neonatal ward. Physical examination is remarkable for the knees being at\nunequal levels when the hips and knees are flexed, asymmetric gluteal folds, and limited abduction of the 