INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('fc251d9ae0ae968b603b','src-v294-5083b15f',NULL,'137','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','Tom, 10 years old, is brought to your clinic by his mother who is concerned about his height and weight. She says Tom has always
been the biggest boy in his classes since he started school. On examination, his weight and height are on 96 and 97 percentile,
respectively. Which one of the following would be the most important initial evaluation to consider?',NULL,'D','For children and adolescents aged 2—18 years, growth is monitored based on age, height, and weight, using sex-specific Body
Mass Index (BMI) percentile charts. BMI is not a fixed measure in this age group but varies with normal growth, stage of puberty,
and sex. Either the United States Centers for Disease Prevention and Control (US-CDC) or WHO BMI percentile charts may be
used, with the same chart used over time to allow for consistent monitoring of growth.

The US-CDC categorizes overweight as between the 85" and 5th percentile and obesity as above the g5th percentile. The WHO

categorizes overweight as between the 85''" and 97'' BMI percentiles and obesity as above the 97" percentile. These categories
are not diagnostic but contribute to the overall clinical impression of the child or adolescent being measured.

Tom, based on either chart, is obese. The likelihood that childhood overweightness and obesity will persist into adulthood
increases with the age of the child and with the presence of parental obesity. One of the strongest predictors of a child’s weight is
the weight status of his/her parents. For overweight or obese children, initial assessment by history and clinical assessment should
determine current health problems and risks for future disease.

History taking includes developmental history, physical and mental health (including family history of obesity), and current health
behaviors.

Clinical assessment includes pubertal stage, possible causes for overweightness or obesity (e.g., hypothyroidism), and indicators
of comorbidities (e.g., metabolic syndrome, raised blood pressure, joint pain, gastrointestinal symptoms, insulin resistance,
intertrigo, dental health etc.)

Of the options, measuring blood glucose is the most important investigation to consider at this stage as well as a lipid profile and
liver function tests. Obese children are at increased risk of metabolic syndromes and the condition should be identified and
addressed early in the course of assessment and treatment.

It is also very important that secondary causes for obesity are considered and excluded. Hypothyroidism can be a potential cause
of obesity; however, the prevalence of hypothyroidism in overweight and obese children and adolescents is not greater than in
normal-weight ones. Given these, measuring TSH (option A) would be an appropriate option if the clinical picture is suggestive of
hypothyroidism or if no apparent cause for overweightness or obesity can be identified. It is however important to note that the
prevalence of hypothyroidism is not greater than in normal-weight children and adolescents.

(Option B) Urine cortisol level would have been indicated if Tom had clinical features suggestive of Cushing syndrome such as
moon face, central obesity, etc.

(Option C) Bone age is often used as the initial assessment for short stature that is not the problem here.

(Option E) This child does not have any alarming features necessitating brain imaging using MRI or CT scan.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[137],"source_qid":null,"duplicate_group_id":"exact-8bdfda36eccf","duplicate_sources":[{"record_id":"fc251d9ae0ae968b603b","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":137,"source_qid":null},{"record_id":"c5431e16461a2843efc3","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":125,"source_qid":null},{"record_id":"4f3796db86866b25f56b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1395,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_an