INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('0ff30e78fbf809df5371','Pediatric amedex 2025.pdf','138','Paediatrics','Lucy has presented to your office concerned about her 3-years-old daughter. Lucy has past medical
history of asthma and eczema and heard that these conditions can run in families. She wants to know
about the risk of her daughter developing asthma or eczema as well. In consulting her, which one of
the following would be the most appropriate advice you can give to minimize the risk allergic
reactions in the child?','{"A":"A. Avoid monosodium glutamate in foods.","B":"B. Avoid contact with sheepskin clothes.","C":"OC. Minimizing household dust mites.","D":"D.No specific advice is needed.","E":"E. Giving the child antihistamines in case allergy develops."}','C','Household dust mites are the most common allergens that can cause allergy and asthma in
genetically susceptible individuals. About 90% of children with atopic symptoms and asthma
demonstrate positive skin-prick responses to dust mite extract.

In general, reducing dust mites is the most appropriate advice here. Avoiding contact with sheepskin
bedding and clothes is a part of measures taken to reduce dust mites.

Anti-histamines and avoiding mono-sodium glutamate in food is not recommended for minimizing the
risk of atopy in children.

Current evidence suggests that exposure to dust mite allergen can be minimized by:

e Encasing mattresses, pillows and blankets/doonas in dustproof covers
¢ Polishing floors and replacing carpet

¢ Washing bed clothes in hot water (>55°C) weekly

e Not using sheepskin bedding','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[138],"source_qid":null,"duplicate_group_id":"exact-c343ac78c2ce","duplicate_sources":[{"record_id":"0ff30e78fbf809df5371","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":138,"source_qid":null},{"record_id":"202605a8a8a8c19e458f","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":66,"source_qid":null},{"record_id":"fa736bbe6dd91afe0ee1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1262,"source_qid":"368"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"0ff30e78fbf809df5371","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":138,"supporting_pages":[138],"source_qid":null,"domain_hint":"Paediatrics","stem":"Lucy has presented to your office concerned about her 3-years-old daughter. Lucy has past medical\nhistory of asthma and eczema and heard that these conditions can run in families. She wants to know\nabout the risk of her daughter developing asthma or eczema as well. In consulting her, which one of\nthe following would be the most appropriate advice you can give to minimize the risk allergic\nreactions in the child?","options":{"A":"A. Avoid monosodium glutamate in foods.","B":"B. Avoid contact with sheepskin clothes.","C":"OC. Minimizing household dust mites.","D":"D.No specific advice is needed.","E":"E. Giving the child antihistamines in case allergy develops."},"source_answer":"C","source_explanation":"Household dust mites are the most common allergens that can cause allergy and asthma in\ngenetically susceptible individuals. About 90% of children with atopic symptoms and asthma\ndemonstrate positive skin-prick responses to dust mite extract.\n\nIn general, reducing dust mites is the most appropriate advice here. Avoiding contact with sheepskin\nbedding and clothes is a part of measures taken to reduce dust mites.\n\nAnti-histamines and avoiding mono-sodium glutamate in food is not recommended for minimizing the\nrisk of atopy in children.\n\nCurrent evidence suggests that exposure to dust mite allergen can be minimized by:\n\ne Encasing mattresses, pillows and blankets/doonas in dustproof covers\n¢ Polishing floors and replacing carpet\n\n¢ Washing bed clothes in hot water (>55°C) weekly\n\ne Not using sheepskin bedding","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["asthma"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"c343ac78c2ce396730675421521236ab03b68024","duplicate_group_id":"exact-c343ac78c2ce","duplicate_sources":[{"record_id":"0ff30e78fbf809df5371","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":138,"source_qid":null},{"record_id":"202605a8a8a8c19e458f","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":66,"source_qid":null},{"record_id":"fa736bbe6dd91afe0ee1","record_type":"text_mcq","source_file":"Amedex 