INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('998f9d193c94c03d3bd0','Pediatric amedex 2025.pdf','140','Paediatrics','A 10-year-old boy is referred to your clinic from his school for assessment of probable hearing deficit because he has difficulty in hearing resulting
in dropped school performance. You carry out a Rinne test that is positive in both ears. A Weber test shows no lateralization; however, he has
symmetrical decreased hearing threshold. Which one of the following options could be the most likely diagnosis?','{"A":"A. Presbycusis.","B":"B. Otosclerosis.","C":"OC. Congenital sensorineural deafness.","D":"D. Chronic perforation of the tympanic membrane.","E":"E. Chronic secretory otitis media with effusion."}','C','In clinical practice it is common to see patients complaining of hearing loss. It is useful to be able to have a simple test that can distinguish where
the site of the cause of the hearing loss is. This can help guide the need for further examination, investigation and management. Rinne’s test and
Weber’s test are done to differentiate between a conductive (middle and outer ear causes) and a sensorineural deafness (caused by damage to
the cochlea or to the 8th nerve — or its central connections). These tests are always done together. The Rinne test is done first.

The function of the external ear is to collect sounds vibrations form the air and focus these onto the tympanic membrane. These vibrations are
then transmitted through the middle ear cavity by the ossicular chain (Malleus, Incus and Stapes). The stapes transmits these vibrations to the
cochlea through the oval window (fenestra ovalis). Sound can also be transmitted through the bones of the skull to the cochlea. The hair cells in
the cochlea convert the physical vibrations into action potentials that are transmitted via the nerves in the vestibulo-cochlear (auditory) nerve to the
brainstem for further processing.

The Rinne and Weber tests are used for quick screening of conductive versus sensorineural hearing loss. The Rinne test is performed for
evaluation of hearing loss in one ear (unilateral hearing loss) and compares perception of sound transmitted by air conduction to those transmitted
by bone conduction through the mastoid. Therefore, there presence of conductive hearing loss is screened for.

For the Rinne test, a vibrating tuning fork (typically 512 Hz) is placed initially on the mastoid process behind each ear until sound is no longer
heard, signaled by the patient. The fork is then immediately positioned just outside the ear with the patient asked to report when the sound caused
by the vibration is no longer heard. A normal or positive Rinne test is when the sound heard outside the ear (air conduction or AC) is louder than
the initial sound heard when the tuning fork end is placed on mastoid process behind the ear (bone conduction or BC). Therefore, AC > BC; which
is how it is reported clinically for a normal or positive Rinne result. In conductive hearing loss, bone conduction is better than air or BC > AC,

a negative Rinne.

In the Weber test, a vibrating tuning fork (often 256Hz or 512Hz) is placed in the middle of the forehead, or above the upper lip under the nose
over the teeth, or on top of the head in an equal distant from the patient’s ears. The patient is then asked to report in which ear the sound is
louder. A Weber test result is normal (positive) if the patient reports the sound equally on both sides. Lateralization (hearing the sound better in
one ear) is due to either a sensorineural or conductive problem. In a patient with sensorineural hearing loss, the normal ear hears the sound better
than the defective one. In a patient with conductive hearing loss, the sound is lateralized to the affected side.

NOTE -— Patients with symmetrical hearing loss have also a positive (normal) Weber test result because both ears are affected equally and no
lateralization occurs despite the fact that there is hearing loss.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[140],"source_qid":null,"duplicate_group_id":"exact-190091619f82","duplicate_sources":[{"record_id":"998f9d193c94c03d3bd0","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":140,"source_qid":null},{"record_id":"3646953c08eb1402dc1b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1345,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"998f9d193c94c03d3bd0","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":140,"supporting_pages":[140],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 10-year-old boy is referred to your clinic from his school for assessment of probable hearing deficit because he has difficulty in hearing resulting\nin dropped school performance. You carry out a Rinne test that is positive in both ears. A Weber test shows no lateralization; however, he has\nsymmetrical decreased hearing threshold. Which one of the following options could be the most likely diagnosis?","options":{"A":"A. Presbycusis.","B":"B. Otosclerosis.","C":"OC. Congenital sensorineural deafness.","D":"D. Chronic perforation of the tympanic membrane.","E":"E. Chronic secretory otitis media with effusion."},"source_answer":"C","source_explanation":"In clinical practice it is common to see patients complaining of hearing loss. It is useful to be able to have a simple test that can distinguish where\nthe site of the cause of the hearing loss is. This can help guide the need for further examination, investigation and management. Rinne’s test and\nWeber’s test are done to differentiate between a conductive (middle and outer ear causes) and a sensorineural deafness (caused by damage to\nthe cochlea or to the 8th nerve — or its central connections). These tests are always done together. The Rinne test is done first.\n\nThe function of the external ear is to collect sounds vibrations form the air and focus these onto the tympanic membrane. These vibrations are\nthen transmitted through the middle ear cavity by the ossicular chain (Malleus, Incus and Stapes). The stapes transmits these vibrations to the\ncochlea through the oval window (fenestra ovalis). Sound can also be transmitted through the bones of the skull to the cochlea. The hair cells in\nthe cochlea convert the physical vibrations into action potentials that are transmitted via the nerves in the vestibulo-cochlear (auditory) nerve to the\nbrainstem for further processing.\n\nThe Rinne and Weber tests are used for quick screening of conductive versus sensorineural hearing loss. The Rinne test is performed for\nevaluation of hearing loss in one ear (unilateral hearing loss) and compares perception of sound transmitted by air conduction to those transmitted\nby bone conduction through the mastoid. Therefore, there presence of conductive hearing loss is screened for.\n\nFor the Rinne test, a vibrating tuning fork (typically 512 Hz) is placed initially on the mastoid process behind each ear until sound is no longer\nheard, signaled by the patient. The fork is then immediately positioned just outside the ear with the patient asked to report when the sound caused\nby the vibration is no longer heard. A normal or positive Rinne test is when the sound heard outside the ear (air conduction or AC) is louder than\nthe initial sound heard when the tuning fork end is placed on mastoid process behind the ear (bone conduction or BC). Therefore, AC > BC; which\nis how it is reported clinically for a normal or positive Rinne result. In conductive hearing loss, bone conduction is better than air or BC > AC,\n\na negative Rinne.\n\nIn the Weber test, a vibrating tuning fork (often 256Hz or 512Hz) is placed in the middle of the forehead, or above the upper lip under the nose\nover the teeth, or on top of the head in an equal distant from the patient’s ears. The patient is then asked to report in which ear the sound is\nlouder. A Weber test result is normal (positive) if the patient reports the sound equally on both sides. Lateralization (hearing the sound better in\none ear) is due to either a sensorineural or conductive problem. In a patient with sensorineural hearing loss, the normal ear hears the sound better\nthan the defective one. In a patient with conductive hearing loss, the sound is lateralized to the affected side.\n\nNOTE -— Patients with symmetrical hearing loss have also a positive (normal) Weber test result because both ears are affected equally and no\nlateralization occurs despite the fact that there is hearing loss.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","screen","screening"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"190091619f82b35704fa6192a9671763f64b7447","duplicate_group_id":"exact-190091619f82","duplicate_sources":[{"record_id":"998f9d193c94c03d3bd0","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":140,"source_qid":null},{"record_id":"3646953c08eb1402dc1b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1345,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
