INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('998f9d193c94c03d3bd0','src-v294-5083b15f',NULL,'140','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','A 10-year-old boy is referred to your clinic from his school for assessment of probable hearing deficit because he has difficulty in hearing resulting
in dropped school performance. You carry out a Rinne test that is positive in both ears. A Weber test shows no lateralization; however, he has
symmetrical decreased hearing threshold. Which one of the following options could be the most likely diagnosis?',NULL,'C','In clinical practice it is common to see patients complaining of hearing loss. It is useful to be able to have a simple test that can distinguish where
the site of the cause of the hearing loss is. This can help guide the need for further examination, investigation and management. Rinne’s test and
Weber’s test are done to differentiate between a conductive (middle and outer ear causes) and a sensorineural deafness (caused by damage to
the cochlea or to the 8th nerve — or its central connections). These tests are always done together. The Rinne test is done first.

The function of the external ear is to collect sounds vibrations form the air and focus these onto the tympanic membrane. These vibrations are
then transmitted through the middle ear cavity by the ossicular chain (Malleus, Incus and Stapes). The stapes transmits these vibrations to the
cochlea through the oval window (fenestra ovalis). Sound can also be transmitted through the bones of the skull to the cochlea. The hair cells in
the cochlea convert the physical vibrations into action potentials that are transmitted via the nerves in the vestibulo-cochlear (auditory) nerve to the
brainstem for further processing.

The Rinne and Weber tests are used for quick screening of conductive versus sensorineural hearing loss. The Rinne test is performed for
evaluation of hearing loss in one ear (unilateral hearing loss) and compares perception of sound transmitted by air conduction to those transmitted
by bone conduction through the mastoid. Therefore, there presence of conductive hearing loss is screened for.

For the Rinne test, a vibrating tuning fork (typically 512 Hz) is placed initially on the mastoid process behind each ear until sound is no longer
heard, signaled by the patient. The fork is then immediately positioned just outside the ear with the patient asked to report when the sound caused
by the vibration is no longer heard. A normal or positive Rinne test is when the sound heard outside the ear (air conduction or AC) is louder than
the initial sound heard when the tuning fork end is placed on mastoid process behind the ear (bone conduction or BC). Therefore, AC > BC; which
is how it is reported clinically for a normal or positive Rinne result. In conductive hearing loss, bone conduction is better than air or BC > AC,

a negative Rinne.

In the Weber test, a vibrating tuning fork (often 256Hz or 512Hz) is placed in the middle of the forehead, or above the upper lip under the nose
over the teeth, or on top of the head in an equal distant from the patient’s ears. The patient is then asked to report in which ear the sound is
louder. A Weber test result is normal (positive) if the patient reports the sound equally on both sides. Lateralization (hearing the sound better in
one ear) is due to either a sensorineural or conductive problem. In a patient with sensorineural hearing loss, the normal ear hears the sound better
than the defective one. In a patient with conductive hearing loss, the sound is lateralized to the affected side.

NOTE -— Patients with symmetrical hearing loss have also a positive (normal) Weber test result because both ears are affected equally and no
lateralization occurs despite the fact that there is hearing loss.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[140],"source_qid":null,"duplicate_group_id":"exact-190091619f82","duplicate_sources":[{"record_id":"998f9d193c94c03d3bd0","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":140,"source_qid":null},{"record_id":"3646953c08eb1402dc1b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1345,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
