INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('23ca6cee298199689d40','Psychiatry  Amedex 2025.pdf','3','Mental Health','Jarred, 15 years old, is brought to you by his concermed parents for assessment. According to
them, he recently has significantly declined school performance. He is quite withdrawn and barely
