INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a1226b01d2e6e88a758a','Psychiatry  Amedex 2025.pdf','209','Mental Health','Dissociative disorders include:
D lative sia:
Significant episodes of amnesia in which the person cannot recall important and often emotionally
charged memories. The amnesia can be general or selective for specific events.
Dissociative fugue:
Sudden, unexpected travel, accompanied by the inability to remember one’s past, confusion about
personal identity, or the assumption of a new identity. Most episodes are isolated and may last from
hours to months. Resolution is usually rapid, but amnesia may last longer.
Dissociative identity disorder (formerly multiple personality disorder);
The presence of multiple, distinct personalities that recurrently control the person''s behaviour,
accompanied by a failure to recall personal information.
NOTE - borderline personality disorder, factitious disorder and malingering are the most important
differential diagnoses to consider for dissociative identity disorder.
Depersonalisation:
The person often describes the condition as an ‘out-of-body experience’.','{"A":"Derealization:","B":"During episodes of derealization, the person perceives the environment as distorted or strange.\nFeelings of being detached from physical surroundings, jamais vu (a sense of familiar things being","C":"strange), déja vu (a sense of unfamiliar things being familiar), and other forms of perceptual distortion\nmay occur.","D":"A psychological stressor is the main risk factor for most dissociative disorders. For dissociative disorder,\nprolonged childhood sexual has been hypothesised to be the most significant risk factor.","E":"Reference(s) + Medscape - Dissociative Disorders"}',NULL,NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Psychiatry  Amedex 2025.pdf","supporting_pages":[209],"source_qid":null,"duplicate_group_id":"exact-844d1a792841","duplicate_sources":[{"record_id":"a1226b01d2e6e88a758a","record_type":"text_mcq","source_file":"Psychiatry  Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Psychiatry  Amedex 2025.pdf","source_page":209,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural_no_qmark","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"a1226b01d2e6e88a758a","source_file":"Psychiatry  Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Psychiatry  Amedex 2025.pdf","source_year":2025,"source_page":209,"supporting_pages":[209],"source_qid":null,"domain_hint":"Mental Health","stem":"Dissociative disorders include:\nD lative sia:\nSignificant episodes of amnesia in which the person cannot recall important and often emotionally\ncharged memories. The amnesia can be general or selective for specific events.\nDissociative fugue:\nSudden, unexpected travel, accompanied by the inability to remember one’s past, confusion about\npersonal identity, or the assumption of a new identity. Most episodes are isolated and may last from\nhours to months. Resolution is usually rapid, but amnesia may last longer.\nDissociative identity disorder (formerly multiple personality disorder);\nThe presence of multiple, distinct personalities that recurrently control the person''s behaviour,\naccompanied by a failure to recall personal information.\nNOTE - borderline personality disorder, factitious disorder and malingering are the most important\ndifferential diagnoses to consider for dissociative identity disorder.\nDepersonalisation:\nThe person often describes the condition as an ‘out-of-body experience’.","options":{"A":"Derealization:","B":"During episodes of derealization, the person perceives the environment as distorted or strange.\nFeelings of being detached from physical surroundings, jamais vu (a sense of familiar things being","C":"strange), déja vu (a sense of unfamiliar things being familiar), and other forms of perceptual distortion\nmay occur.","D":"A psychological stressor is the main risk factor for most dissociative disorders. For dissociative disorder,\nprolonged childhood sexual has been hypothesised to be the most significant risk factor.","E":"Reference(s) + Medscape - Dissociative Disorders"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural_no_qmark","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"844d1a792841c9554fc63b18805cd868953480ca","duplicate_group_id":"exact-844d1a792841","duplicate_sources":[{"record_id":"a1226b01d2e6e88a758a","record_type":"text_mcq","source_file":"Psychiatry  Amedex 2025.pdf","source_relative_p